window.EXECUTION_MATERIAL=(window.EXECUTION_MATERIAL||[]).concat([{"kind":"heading","text":"الفصل الثاني: المنع من السفر"},{"kind":"text","text":"الحكمة منه"},{"kind":"text","text":"424- هو من الإجراءات الاحتياطية التي تستهدف الضغط على إرادة المدين لكي يقوم بالوفاء، ويجنب بالتالي الدائن وسلطة التنفيذ عناء القيام بالتنفيذ الجبري. وهو يشترك في ذلك مع الحبس، وإن كان أخف منه وطأة."},{"kind":"text","text":"ولذلك كانت شروط إصدار الأمر به أخف حدة هي الأخرى. يكفي أن إصداره لا يتطلب وجود سند تنفيذي بيد الدائن."},{"kind":"heading","text":"المبحث الأول: شروط المنع من السفر"},{"kind":"heading","text":"425- يشترط لمنع المدين من السفر صدور أمر قضائي بذلك. هذا الأمر لا يصدر إلا نتيجة توافر جملة شروط."},{"kind":"text","text":"(أ) فأول شروط المنع من السفر هو صدور أمر بذلك من القاضي المختص، وهو في الحقيقة أكثر من قاض:"},{"kind":"text","text":"1- فهو قد يكون قاضي الموضوع. فالفرض الآن أن هناك دعوى موضوعية مرفوعة بالفعل للمطالبة بدين من الديون. هنا يكون القاضي المرفوعة أمامه هذه الدعوى مختصا بإصدار أمر المنع من السفر (مادة 1-321). فقاضي الدائرة المدنية المرفوع أمامها دعوى المديونية مثلا هو المختص بمنع المدين- وهو المدعى عليه عادة - من السفر."},{"kind":"text","text":"وتجب ملاحظة أن الدعوى الموضوعية التي يمكن استصدار أمر المنع من السفر من قاضيها يجب أن تكون دعوى إلزام وليست مجرد تقرير أو إنشاء. هذه الملاحظة تجد أساسها في أن الغاية من منع المدين من السفر هي إجباره على التنفيذ الاختياري، بينما الحكم الصادر في الدعوى التقريرية أو دعوى الإنشاء، لا يحتاج إلى مثل هذا التنفيذ. والذي يمكن أن يدعم وجهة نظرنا هذه، ما ورد في البند 5 من المادة 325، والذي يقرر سقوط أمر المنع من السفر إذا لم يبدأ المحكوم له في تنفيذ الحكم النهائي الصادر في الدعوى الموضوعية خلال مهلة معينة. فالحديث عن \"تنفيذ\" حكم، يفيد بطريق اللزوم العقلي، أن الدعوى التي صدر فيها كانت دعوى إلزام."},{"kind":"text","text":"2- وهو قد يكون قاضي الأمور المستعجلة. والفرض هنا أن الدعوى الموضوعية لم ترفع بعد، ويريد الدائن استصدار أمر بمنع مدينه من السفر. ولا يمانع المشرع من إصدار ه في هذا الفرض. فالبند (1) من المادة 324 يشير صراحة إلى جواز إصدار هذا الأمر\" ولو قبل رفع الدعوى الموضوعية\". إلا أن النصوص لم تحدد القاضي المختص في هذه الحالة. وليس أمامنا عندئذ سوى القول بأن الاختصاص يكون لقاضي الأمور المستعجلة. فالأمر بالمنع من السفر ينتمي إلى طائفة الأوامر على عرائض، والتي أعطاها المشرع إلى هذا القاضي بنص صريح في أكثر من مناسبة، مما يعني أن اختصاصه بأمر المنع من السفر لن يكون غريبا عليه. ثم إننا في حقيقة الأمر بصدد مسألة يخشى عليها من فوات الوقت، وهي مناط اختصاص القاضي المستعجل."},{"kind":"text","text":"يجب هنا أيضا – وتأسيسا على ما قلناه حالا- أن تكون الدعوى الموضوعية التي لم ترفع بعد دعوى إلزام. بل ويجب رفعها بالفعل خلال ثمانية أيام من صدور الأمر، وإلا جاز استصدار أمر آخر بسقوطه (مادة 5- 325)."},{"kind":"text","text":"3- ثالث قاض مختص بإصدار أمر المنع من السفر، هو قاضي التنفيذ. فقد أعطاه المشرع الاختصاص بنص صريح في فرض محدد، هو عندما يكون بيد الدائن سند تنفيذي، ويرغب في استصدار أمر بمنع مدينه من السفر، قبل أن يعلمه بنيته في وضع هذا السند موضع التنفيذ."},{"kind":"text","text":"(ب) وأيا كان القاضي المختص، فإنْ الأمر لن يصدر من تلقاء نفس القاضي، وإنما لابد له من طلب. وبالفعل يستفاد بسهوله من المادة 324 ضرورة تقديم طلب من جانب الدائن. هذا الطلب ليس دعوى قضائية ولا تترتب على تقديمه خصومة، وإنما يقدم دون إعلان لكي يصدر بناء عليه أمر في غفلة من المدين. ومع ذلك يقرر النص أن \"للقاضي قبل إصدار الأمر، أن يجري تحقيقا مختصرا إذا لم تكفه المستندات المؤيدة للطلب.. \" (مادة 2- 324). وفي الحقيقة فإن أمر المنع من السفر هو أمر على عريضة، يخضع لقواعده فيما لم يرد بشأنه نص خاص، ولذلك فإن الطلب يقدم في شكل عريضة من نسختين مشتملة على وقائع الطلب وأسانيده والأسباب الجدية التي يخشى معها فرار المدين."},{"kind":"text","text":"(ج) ووفقا للمادة 1- 324 فإن هناك شروطا موضوعية ثلاثة يجب توافرها لكي يستجيب القاضي للطلب. الشرط الأول أن يثبت الدائن وجود أسباب يخشى معها فرار المدين. والشرط الثاني ألا يقل الدين الذي يلتزم به المدين عن (10000) عشرة آلاف درهم). أما الشرط الثالث فهو أن يكون الدين معين المقدار ومستحق الأداء وغير مقيد بشرط."},{"kind":"heading","text":"المبحث الثاني: أحكام المنع من السفر"},{"kind":"text","text":"أولا: سقوط أمر المنع من السفر"},{"kind":"text","text":"426- المفروض أن أمر المنع من السفر يبقى ساري المفعول إلى أن يسقط. وهو لا يسقط تلقائيا وإنما بصدور أمر بذلك من القاضي المختص، وهو القاضي مصدر الأمر. هذا الأخير لا يستطيع بدوره إصدار الأمر بالسقوط من تلقاء نفسه وإنما بناء على طلب تطبيقا للقواعد العامة. وقد حددت المادة 325 الحالات التي يصدر فيها الأمر بالسقوط وهي:"},{"kind":"text","text":"1-إذا سقط أي شرط من الشروط اللازم توافرها للأمر بالمنع من السفر. ولعل أبرز تطبيق لهذه الحالة أن ينقضي التزام المدين، أو أن تبين براءة ذمته عند نظر الدعوى الموضوعية."},{"kind":"heading","text":"2- إذا وافق الدائن كتابة على إسقاط الأمر."},{"kind":"text","text":"3-إذا قدم المدين كفالة مصرفية كافية، أو كفيلا مقتدرا يقبله القاضي."},{"kind":"text","text":"4- إذا أودع المدين خزانة المحكمة مبلغا من النقود مساويا للدين والمصروفات وخصص للوفاء بحق الدائن الذي صدر الأمر بناء على طلبه، ويعتبر هذا المبلغ محجوزا عليه بقوة القانون لصالح الدائن."},{"kind":"text","text":"5- إذا لم يقدم الدائن للقاضي ما يدل على رفع الدعوى بالدين خلال ثمانية أيام من صدور الأمر بالمنع من السفر. وتفترض هذه الحالة أن الدائن كان قد استصدر أمرا بالمنع من قاضي الأمور المستعجلة قبل رفع الدعوى الموضوعية، وهو فرض جائز كما سبق أن بينا."},{"kind":"heading","text":"6- إذا لم يبدأ الدائن في تنفيذ الحكم النهائي الصادر لصالحه خلال ثلاثين يوما من تاريخ صيرورته قطعيا."},{"kind":"text","text":"وأول ما يلاحظ على صياغة هذه الحالة من حالات السقوط أنها تفترض أنه لم يكن بيد الدائن سند تنفيذي وقت أن صدر أمر المنع السفر، ثم حصل عليه بعد ذلك في صورة حكم قضائي نهائي. أما إذا كان بيده هذا الحكم قبل أن يصدر أمر المنع من السفر، فلن تثور الحالة محل البحث، لأن أمر المنع في هذا الفرض إنما يصدر من قاضي التنفيذ بمناسبة التقدم بطلب التنفيذ بالفعل."},{"kind":"text","text":"أما ثاني الملاحظات فهي صيرورة الحكم قطعيا والتي يجعلها النص الواقعة المجرية للميعاد. والواقع أنه لا يوجد أي معنى لاستناد النص إلى هذه الصفة. فالصفة القطعية صفة ملازمة للحكم القضائي منذ مولده، وبالتالي كان يجب أن تكون صياغة النص بحيث يسري الميعاد من تاريخ صدوره نهائيا أو صيرورته كذلك، دون أي اعتبار لصفة القطعية، وذلك لأن هذه الأخيرة متواجدة بالضرورة مع تواجد الحكم النهائي، بل وحتى غير النهائي."},{"kind":"text","text":"أما ثالث الملاحظات فهي أنه أمام صراحة عبارة النص والتي تتكلم عن الحكم \"النهائي\"، فإن ميعاد الثلاثين يوما لا يبدأ إذا كان الحكم ابتدائيا ومشمولا بالنفاذ المعجل، ويعتبر بالتالي سندا تنفيذيا يسمح له بالبدء في التنفيذ."},{"kind":"heading","text":"7- إذا انقضت ثلاث سنوات على آخر إجراء صحيح من إجراءات تنفيذ الحكم النهائي دون التقدم بطلب الاستمرار في مباشرة التنفيذ."},{"kind":"text","text":"8- إذا ورد طلب من الجهات المختصة ان إقامة الممنوع من السفر في الدولة أصبحت غير قانونية ويتعين إبعاده منها ولم يثبت وجود أموال له في الدولة يمكن التنفيذ عليها."},{"kind":"text","text":"ثانيا: وقف تنفيذ أمر المنع من السفر"},{"kind":"text","text":"427- يجوز لرئيس المحكمة التي يتبعها القاضي الذي أصدر أمرا بمنع المدين من السفر أن يعطل تنفيذ هذا الأمر مع بقائه قائما، ويصدر أمرا بالموافقة على سفره بناء على طلبه، بسبب حاجته هو أو حاجة أحد أصوله أو فروعه من الدرجة الأولى أو زوجه، إلى العلاج في الخارج (مادة 6- 324)."},{"kind":"text","text":"ثالثا: التنازع بين أمر المنع وحكم الإبعاد"},{"kind":"text","text":"428- يوجد بالتأكيد تعارض بين تنفيذ الأمر الصادر بالمنع من السفر وتنفيذ الحكم القضائي الصادر بتدبير الإبعاد. ولأن المتناقضين لا يجتمعان، كان لابد من تنظيم آلية لفض الاشتباك بينهما. ونظرا لعدم منطقية وضع حل محدد يعلي من أحدهما على حساب الآخر على نحو دائم، كان من المناسب أن تعرض مثل هذه الحالات على لجنة خاصة للنظر في تنفيذ أيهما في كل حالة على حدة (مادة 5- 324)."},{"kind":"text","text":"429- وقد يحدث أيضا تعارض بين المنع من السفر والقرار الإداري الصادر بتسليم أجنبي إلى دولة أجنبية وفقا لقانون التعاون القضائي الدولي في المسائل الجنائية. في هذه الحالة، قرر المشرع أن تكون الأولوية لتنفيذ قرار التسليم، ودون الحاجة إلى عرض المسألة على اللجنة أو غيرها (مادة 326)."},{"kind":"text","text":"رابعا: التظلم من أمر المنع من السفر"},{"kind":"text","text":"430- قلنا إن الأمر الصادر بالمنع من السفر هو أمر على عريضة. ولذلك كان طبيعيا أن تقرر المادة 4-324 جواز التظلم منه بالإجراءات المقررة للتظلم من الأوامر على العرائض."},{"kind":"text","text":"والمقصود بالأمر القابل للتظلم، ليس فقط الأمر بالمنع، وإنما أيضا الذي صدر بالرفض. والدليل على ذلك أن الحق في التظلم مقرر لمن صدر أمر بمنعه من السفر أو لمن رفض طلبه (مادة 4-424)."},{"kind":"text","text":"خامسا: الإجراءات الاحتياطية التي قد تلحق بالأمر"},{"kind":"text","text":"431- (أ) ففي حالة إصدار الأمر بالمنع من السفر، للقاضي أن يأمر أيضا بإيداع جواز سفر المدين في خزانة المحكمة، وتعميم الأمر بمنع السفر على جميع منافذ الدولة (مادة 2-324)."},{"kind":"text","text":"432- (ب) وإذا امتنع المدين عن تسليم جواز سفره دون مبرر، أو تبين للقاضي أنه تصرف في أمواله أو هربها، أو تبين أنه يعد العدة للفرار خارج الدولة بالرغم من التدابير المتخذة لمنعه من السفر، فللقاضي أن يقرر إحضاره وإلزامه بتقديم كفالة دفع أو كفالة حضور أو بإيداع المبلغ المدعى به خزانة المحكمة(مادة 327). فإذا لم يمتثل للأمر، فللقاضي أن يقرر التحفظ عليه مؤقتا لحين تنفيذ الأمر (مادة 327)."},{"kind":"heading","text":"الباب الخامس: منازعات التنفيذ"},{"kind":"text","text":"(دراسة للأحكام والأوامر والقرارات الصادرة في منازعات التنفيذ أو عقباته من قاضي التنفيذ- أو من غيره- وطرق مراجعتها)"},{"kind":"text","text":"436- بادئ ذي بدء، يجب أن يكون ماثلا في الذهن أن التنفيذ الجبري إنما يجري تحت إشراف قاضي التنفيذ (مادة 1-206)، كما أن هذا الأخير هو المختص كأصل عام بالفصل في منازعاته (مادة 1-207). وهو يصدر عند ممارسته لوظيفته الأولى هذه أو الثانية – وبحسب الأحوال- قرارا أو أمرا أو حكما."},{"kind":"text","text":"والنتيجة المستفادة من استقراء النصوص أن \"القرار\" هو ما يصدر من قاضي التنفيذ من تلقاء نفسه لإزالة عقبة من عقبات التنفيذ بمناسبة وظيفته الإشرافية."},{"kind":"text","text":"أما \"الأمر\" فهو ما يصدر من قاضي التنفيذ بناء على عريضة تقدم إليه من أحد ذوي الشأن لإزالة عقبة من عقبات التنفيذ."},{"kind":"text","text":"ونقابل القرار أو الأمر في الأحوال التي تجيز فيها النصوص ذلك، إما بمناسبة ممارسة قاضي التنفيذ لوظيفته الإشرافية- وهذا هو الغالب- وإما بمناسبة سير التنفيذ وبصفة وقتية."},{"kind":"text","text":"وأخيرا فإن \"الحكم\" هو ما يصدر من قاضي التنفيذ في خصومة قضائية رفعت إليه من أحد أطراف التنفيذ- المنفذ ضده غالبا- وتتعلق بالتنفيذ."},{"kind":"text","text":"دراسة عقبات التنفيذ ومنازعاته هي إذا دراسة لقرارات قاضي التنفيذ وأوامره وأحكامه."},{"kind":"heading","text":"الفصل الأول: القرارات"},{"kind":"text","text":"437- إلى جانب \"الأحكام القضائية\" التي تصدر من قاضي التنفيذ في خصومة وتقبل الطعن عليها وفقا للقواعد المقررة، وإلى جانب \"الأوامر على عرائض\" التي تصدر منه في أحوال معينة منصوص عليها قانونا وتقبل التظلم منها أيضا وفقا للقواعد العامة (أو وفقا لقواعد خاصة)، فإنه تصدر منه أيضا \"قرارات\" تتعلق بالتنفيذ الجبري، ولا تعتبر أحكاما قضائية ولا أوامر على عرائض. هذه القرارات تصدر من قاضي التنفيذ من تلقاء نفسه عند ممارسته لوظيفته الإشرافية على التنفيذ. ويمكن التعرف على أهم هذه القرارات بمناسبة النص الذي تناول كيفية مراجعتها، سواء كان التظلم أو الاستئناف. على أن هذا الاستنتاج لا يمنع من وجود قرارات أخرى يمكن لقاضي التنفيذ إصدارها، على أن تكون غير قابلة للمراجعة."},{"kind":"text","text":"والطبيعي أن يكون أول قرارات قاضي التنفيذ، القرار الصادر منه باختصاصه أو بعدم اختصاصه. فعندما يتقدم طالب التنفيذ بطلب التنفيذ، فإن على قاضي التنفيذ أن يبحث من تلقاء نفسه مسألة اختصاصه الإشرافي، بحيث إذا تبين له عدم اختصاصه، وجب عليه أن يصدر قرارا بعدم الاختصاص. أما إذا تبين لقاضي التنفيذ أنه مختص، فإن قراراته تتوالى بعد ذلك، والتي يمكن التعرف على معظمها وأهمها، وذلك من خلال التعداد الذي جاءت به المادة 209 والتي نظمت طرق مراجعتها."},{"kind":"text","text":"وتجب ملاحظة أن القرارات الواردة في المادة المذكورة سوف تحتفظ بصفتها هذه لمجرد أنه بإمكان قاضي التنفيذ إصدارها من تلقاء نفسه. ولذلك لن تتغير طبيعتها حتى لو صدرت بناء على طلب أحد ذوي الشأن."},{"kind":"text","text":"ويلاحظ أن عبارة النص التشريعي توحي أحيانا بأن عملا ما من أعمال قاضي التنفيذ يعتبر قرارا، رغم أنه في حقيقة الأمر ليس كذلك. فقد يكون التكييف الصحيح للعمل أنه أمر على عريضة مثلا وليس قرارا. وعندئذ يجب الاعتداد بهذا التكييف وإخضاع العمل للنظام الإجرائي المتفق معه، اللهم إلا إذا كان واضحا أن للمشرع توجها آخر."},{"kind":"text","text":"438- ومن الأهمية الوقوف على ما يعد قرارا، وذلك لتحديد كيفية مراجعته. فهناك طائفة من القرارات أجاز المشرع التظلم منها وبإجراءات مخصوصة، وهناك طائفة ثانية منها أجاز المشرع الطعن عليها بطريق الاستئناف وبإجراءات أيضا مخصوصة. وفيما عدا هذه القرارات أو تلك، فإنه لا تجوز المنازعة في قرارات قاضي التنفيذ. لذلك سوف نستعرض أهم القرارات التي تصدر من قاضي التنفيذ بحسب طريق المراجعة الواجب اتباعه."},{"kind":"heading","text":"المبحث الثاني: قرارات قاضي التنفيذ القابلة للاستئناف"},{"kind":"text","text":"456- الأصل أن قرارات قاضي التنفيذ-وهي ليست أحكاما- لا تقبل الطعن عليها بطرق الطعن المقررة أصلا لمراجعة الأحكام القضائية كالاستئناف، وأن طريق مراجعتها -وبالنظر إلى كونها أعمالا ولائية- هو التظلم، أو ألا تقبل أي طريق من طرق المراجعة. ولقد ساير المشرع من حيث المبدأ هذا الأصل العام فيما يتعلق بالكثير من هذه القرارات وأجاز التظلم منها كما سبق ورأينا."},{"kind":"text","text":"إلا أنه قد خرج في بعض الأحيان على هذا الأصل، وتعامل مع البعض الآخر من قرارات قاضي التنفيذ المعاملة التي تلقاها الأحكام، وأجاز الطعن عليها بالاستئناف."},{"kind":"text","text":"وليس هناك مبرر واضح لجعل بعض قرارات قاضي التنفيذ قابلة للاستئناف وليس للتظلم. فهذا الأخير لا يتم أمام قاضي التنفيذ الذي أصدر القرار وإنما أمام قاض آخر غيره هو رئيس المحكمة أو من يفوضه على ألا يكون هذا الأخير هو مصدر الأمر. هو إذا أقرب للاستئناف. ولذلك كان من المناسب أن تتوحد طريقة المراجعة لكل قرارات قاضي التنفيذ، وتكون هي التظلم."},{"kind":"text","text":"457- وإلى أن يقوم المشرع بتوحيد المعاملة، فإنه في ظل الوضع الحالي تكون بعض قرارات قاضي التنفيذ قابلة للاستئناف أمام محكمة الاستئناف المختصة، مع الوضع في الاعتبار أن هذا الاستئناف يخضع وفقا للمادة 2-209 لبعض الخصوصية مقارنة بإجراءات الاستئناف العادية."},{"kind":"text","text":"سوف نتعرف أولا على أوجه الخصوصية ثم نتعرف بعد ذلك بالتفصيل على القرارات التي تقبل الاستئناف."},{"kind":"heading","text":"المطلب الأول: خصوصيات الطعن بالاستئناف في بعض قرارات قاضي التنفيذ"},{"kind":"text","text":"458- من ناحية أولى، بينما ميعاد الاستئناف كأصل عام ثلاثون يوما، فإن ميعاد استئناف قرارات قاضي التنفيذ عشرة أيام عمل، يبدأ من تاريخ صدور القرار إذا كان حضوريا، ومن تاريخ إعلانه أو العلم به إذا كان غيابيا (مادة 209 - 2)."},{"kind":"text","text":"ومن ناحية ثانية، يجوز للمحكمة التي تنظر الطعن بالاستئناف المرفوع عن الحكم القضائي أن تحكم بوقف تنفيذه لحين الفصل في الطعن (مادة 1-221). على أن نظام الوقف هذا يستلزم بطبيعة الحال توافر شروط معينة في هذا الحكم، منها أن يكون صادرا بإلزام في الموضوع، حتى تكون هناك حاجة إلى وقف تنفيذه. وعلى نفس النسق يجيز المشرع لمحكمة الاستئناف سلطة الحكم بوقف الإجراء الصادر به قرار قاضي التنفيذ محل الطعن، لحين الفصل في النزاع (مادة 3- 209). وقد يبدو لأول وهلة أنه لا توجد هنا ثمة خصوصية لأنه كان يمكن الإقرار بهذه النتيجة بالتطبيق للنص العام الذي يجيز لمحكمة الاستئناف وقف التنفيذ. إلا أن التدقيق في المسألة يقودنا في الحقيقة إلى أهمية ما ورد في المادة 209 حتى نرتب النتيجة المذكورة فيها. فالمتأمل في القرارات المشار إليها في البند (2) من هذه المادة، والتي أجاز البند (3) الأمر بوقفها مؤقتا بمناسبة الطعن عليها بالاستئناف، يدرك أن بعضها ليس محلا لوقف التنفيذ بمعنى الكلمة. ينطبق ذلك على الأقل على قرارين من القرارات الأربعة الواردة في البند (2)، وهما القرار الصادر بشأن الاختصاص وكذلك الصادر بشأن القابلية للحجز. فلولا النص الصريح على جواز وقفهما، ما كان جائزا الحكم به وفقا للنص العام الوارد في المادة 1-221. على أن يكون المقصود بالوقف هنا مجرد عدم ترتيب القرار لمفعوله وعدم الاعتداد به رغم بقائه دون إلغاء."},{"kind":"text","text":"459- وفيما عدا الخصوصيتان السابقتان، سوف تتبع في استئناف قرارات قاضي التنفيذ قواعد وإجراءات الاستئناف العادية. وأما ما يصدر في الطعن بعد ذلك، فإنه سيكون حكما قضائيا بكل معنى الكلمة -وليس قرارا أو أمرا- بالنظر إلى صدوره في خصومة. مع الأخذ في الاعتبار أن هذا الحكم سيكون قابلا للطعن بالنقض."},{"kind":"heading","text":"المطلب الثاني: دراسة تفصيلية لقرارات قاضي التنفيذ القابلة للطعن بالاستئناف"},{"kind":"text","text":"تحدد المادة 2- 209 هذه القرارات بتلك التي تصدر في الأحوال الآتية:"},{"kind":"text","text":"(أ) اختصاص قاضي التنفيذ أو عدم اختصاصه بتنفيذ السند التنفيذي"},{"kind":"text","text":"460- تفترض هذه الحالة تقديم طلب تنفيذ -وهو لا يعد طلبا قضائيا ولا يمثل صحيفة دعوى ولا تنشأ عنه خصومة قضائية- إلى قاضي التنفيذ، فيصدر هذا الأخير قرارا بعدم اختصاصه، أيا كان سببه. فقد لا يتوافر في هذا القاضي أي معيار من معايير الاختصاص المكاني، أو يكون السند المطلوب تنفيذه ليس سندا تنفيذيا، كما لو كان حكما ابتدائيا غير مشمول بالنفاذ، أو كان حكما تقريريا حتى لو كان نهائيا، أو يكون مطلوبا التنفيذ على أموال توجد خارج الدولة. كما تفترض هذه الحالة أيضا أن يحدث العكس، أي أن يقرر قاضي التنفيذ اختصاصه ضمنا -بأن يصدر أمره إلى القائم بالتنفيذ بإجراء التنفيذ-وذلك رغم عدم اختصاصه لأحد الأسباب السابقة أو غيرها."},{"kind":"text","text":"وليس مستبعدا أن يصدر قاضي التنفيذ قراره في مسألة الاختصاص في الصورتين السابقتين ويراه طالب التنفيذ أو المنفذ ضده مشوبا بخطأ في الواقع أو القانون. ولذلك تعامل المشرع مع هذا القرار معاملة مماثلة لتلك التي يلقاها الحكم القضائي الصادر في ذات الشأن، فأجاز الطعن بالاستئناف مباشرة في مجرد قرار الاختصاص أو عدم الاختصاص، الصريح أو الضمني، ودون ولوج طريق التظلم أولا، وعلى خلاف ما هو مقرر عادة في عموم القرارات القضائية التي لا تعتبر حكما. وبناء عليه، فإنه إذا كان القرار صادرا بالاختصاص ولم يستأنفه المنفذ ضده في الميعاد، سقط حقه في الاستئناف كما تقضي بذلك القواعد العامة، وحاز القرار حصانة تمنع المنازعة فيه بعد ذلك من خلال دعوى بطلان التنفيذ أو حتى الإشكال الوقتي."},{"kind":"text","text":"(ب) الأموال المحجوز عليها مما يجوز أو لا يجوز حجزها أو بيعها"},{"kind":"text","text":"461- المفروض أن الدائن هو الذي يحدد الأموال التي يريد توقيع الحجز عليها، ثم يصدر قاضي التنفيذ أوامره إلى القائم بالتنفيذ بالحجز على هذه الأموال أو بعضها. وهذه الأموال قد تكون غير قابلة للحجز. وقد يحدث العكس بأن يمتنع قاضي التنفيذ – وهو ما يشكل قرارا ولو سلبيا- عن إصدار أوامره إلى القائم بالتنفيذ بالحجز على هذه الأموال رغم قابليتها له. فهذا القرار أو ذاك كان خاطئا، نظرا لأن المال كان مما لا يجوز حجزه في المرة الأولى، أو كان مما يجوز حجزه في المرة الثانية. ولذلك لا غرابة في أن يجيز المشرع للمتضرر من القرار، الطعن عليه بالاستئناف. فإذا كان المال المحجوز عليه مما لا يجوز حجزه مثلا، إلا أن المحجوز عليه لم يطعن على قرار الحجز بالاستئناف إلى أن صار غير قابل له، فإنه يكون محصنا وغير قابل حتى للإلغاء من خلال إشكال تنفيذ وقتي أو موضوعي."},{"kind":"text","text":"462- ويلاحظ أن قرار قاضي التنفيذ القابل للاستئناف هنا هو ذلك الذي يدور النزاع حوله على ضوء المادة 242 التي تحدد الأموال التي لا يجوز الحجز عليها. أما إذا كان النزاع يدور حول أن الأموال المحجوزة لا يجوز حجزها لأن قيمتها تجاوز مبدأ التناسب المذكور في المادة 246، فإن مثل هذا القرار لا يندرج في القرار محل البحث ولا يطعن عليه بالاستئناف. ويلاحظ أيضا أنه إذا كان قرار الحجز قد وقع على أموال لا يجوز الحجز عليها لأنها مملوكة لغير المنفذ ضده، فإن هذا القرار لا يدخل فيما يجوز استئنافه طبقا للمادة 2- 209."},{"kind":"text","text":"463- وعموما، فإنه إذا كان القرار المطعون عليه بالاستئناف كان بشأن أموال يجوز أو لا يجوز الحجز عليها، فإن الحكم الصادر في الطعن بعد ذلك من محكمة الاستئناف لن يعتبر صادرا في إجراء من إجراءات التنفيذ البحتة، وبالتالي لن ينطبق عليه المنع من الطعن بالنقض المقرر في المادة 3- 175 من القانون."},{"kind":"text","text":"(ج) اشتراك أشخاص آخرين غير الخصوم في الحجز"},{"kind":"text","text":"464- يقصد بالخصوم في هذا الصدد -بصرف النظر عن عدم ملائمة الكلمة مع التنفيذ الجبري- أطراف التنفيذ الأصليون، أي الدائن الحاجز والمدين المحجوز عليه، وكذلك الدائنون المتدخلون في الحجز، والحائز أو الكفيل العيني في الحجز على العقار، وأخيرا المحجوز لديه في حجز ما للمدين لدى الغير."},{"kind":"text","text":"وبناء عليه، يصبح غير هؤلاء من غير الخصوم، ويدخلون تحت عبارة الفقرة ج من المادة 2- 209. فعبارة الاشتراك في الحجز من غير الخصوم تنطبق أولا على الدائنين أصحاب الحقوق المقيدة على العقار المحجوز. إذ يجب أن يصبح هؤلاء طرفا في الإجراءات كحاجزين بمجرد إعلانهم بالحجز بواسطة القائم بالتنفيذ بناء على قرار يصدر بذلك من قاضي التنفيذ بوصفه المشرف على التنفيذ (مادة 287 - 2)."},{"kind":"text","text":"كما يمكن إطلاق عبارة الاشتراك في الحجز أيضا على ورثة الدائن أو المدين - أو ورثة غيرهما من الخصوم أو المشتركين السابق ذكرهم- إذا حدثت الوفاة بعد الحجز."},{"kind":"text","text":"كما يمكن اعتباره مشتركا في الحجز من غير الخصوم، كل من قام قاضي التنفيذ باعتباره طرفا في الحجز حاجزا أو محجوزا عليه، رغم أنه من غير ممن سبق. كما لو اعتد قاضي التنفيذ بصفة الشريك أو الكفيل مثلا، وأمر بالحجز على المال الخاص لأي منهما، رغم عدم وجود له في السند التنفيذي."},{"kind":"text","text":"وقد يرفض قاضي التنفيذ اشتراك أي ممن يرى أحقيته في الاشتراك في الحجز، أو يقوم بإشراك من ليس له هذا الحق. ولذلك أجاز القانون للمتضرر من هذا القرار أو ذاك الطعن فيه بالاستئناف طبقا للإجراءات المقررة في المادة 2– 209."},{"kind":"text","text":"(د) قرار حبس المدين أو رفض حبسه"},{"kind":"text","text":"465- سبق أن وقفنا على أن لقاضي التنفيذ أن يصدر أمرا بحبس المدين، بناء على طلب يقدم من الدائن الذي بيده سند تنفيذي، عند توافر مقتضيات معينة، وانتفاء بعض الموانع، وذلك وفقا للمواد 323 – 319."},{"kind":"text","text":"فإذا صدر قرار أو أمر الحبس، جاز للمدين استئنافه وفقا للإجراءات المقررة في المادة 2- 209."},{"kind":"text","text":"هذا الاستئناف لقرار الحبس يخضع بطبيعة الحال لخصوصيات الاستئناف السابق ذكرها، والخاصة بقرارات قاضي التنفيذ القابلة للاستئناف."},{"kind":"text","text":"ولكن بالإضافة إلى ذلك توجد خصوصية أخرى تتعلق باستئناف أمر الحبس، وهي أن على المستأنف تقديم كفيل يكون مسؤولا عن إحضار المدين أو الوفاء بالمبلغ المحكوم به (مادة 1- 209- د). ويعتبر ذلك شرطا لقبول الاستئناف، بحيث يجب الحكم بعدم قبوله عند تخلفه."},{"kind":"text","text":"466- والقرار القابل للاستئناف ليس فقط الصادر بالحبس وإنما أيضا - وبصريح النص-الصادر بالرفض. ولا مانع من قيام الدائن الذي رفض طلبه باستئناف القرار أو التقدم بطلب ثان أو أكثر بالحبس، إذ أن قرار الرفض لا يحوز حجية تمنع من الرجوع فيه."},{"kind":"text","text":"467- وتنطبق بالتأكيد عبارة رفض الحبس على قرار قاضي التنفيذ بالإفراج عن المدين الذي سبق أن صدر أمر بحبسه، وبالتالي يجوز استئنافه."},{"kind":"text","text":"468- وفي النهاية تجدر الملاحظة أنه إذا كان القرار المطعون عليه بالاستئناف كان بشأن الحبس، فإن الحكم الصادر في الطعن بعد ذلك من محكمة الاستئناف لن يعتبر صادرا في إجراء من إجراءات التنفيذ البحتة، وبالتالي لن ينطبق عليه المنع من الطعن بالنقض المقرر في المادة 3- 175 من القانون."},{"kind":"text","text":"(ه) القرار الصادر بشأن تحديد المبلغ المنفذ به والاستمرار في تنفيذه من عدمه"},{"kind":"text","text":"469- لا يجوز إقامة دعوى مستقلة أمام محكمة الموضوع بخصوص بيان ما سدد وما تبقى أثناء التنفيذ. فهذه مسألة متعلقة بالتنفيذ مما يختص بها قاضي التنفيذ دون غيره. إلا أنه لا يجوز رفع هذه الدعوى حتى أمامه. ذلك لأن المشرع حدد طريقا آخر لكيفية تحديد هذه المبالغ. هذا الطريق هو \"القرار\"."},{"kind":"text","text":"ولذلك لا مانع من أن يصدر أولا قرار من قاضي التنفيذ، ولو بناء على طلب يقدم أثناء التنفيذ، بندب خبير حسابي لبيان قيمة المبالغ التي استلمها طالب التنفيذ وما تبقى له في ذمة المنفذ ضده."},{"kind":"text","text":"وعلى ضوء نتيجة هذا التقرير يصدر قاضي التنفيذ قرار ا بتحديد المبلغ المنفذ به. ولا مانع بعد ذلك من صدور قرار لاحق بالاستمرار في التنفيذ أو بعدم الاستمرار فيه، كما لو تبين مثلا استيفاء طالب التنفيذ لكافة حقوقه المالية."},{"kind":"text","text":"470- وأخيرا تجدر الملاحظة أن القرار الصادر بتحديد مقدار المديونية التي ينفذ لأجلها لا يعد قرارا تنفيذيا بحتا في مفهوم المادة 3-175، وبالتالي فإن الحكم الصادر في استئناف هذا القرار يعتبر قابلا للطعن."},{"kind":"heading","text":"المبحث الأول: قرارات قاضي التنفيذ القابلة للتظلم"},{"kind":"text","text":"439- أتى على قاضي التنفيذ حين من الدهر لم يكن التظلم من قراراته متاحا، فقد كان الطعن بالاستئناف هو فقط المتاح أمام بعض قراراته. أما اليوم، فإنه إلى جانب الاستئناف المتاح تجاه بعض القرارات، نظم القانون التظلم من بعضها الآخر، وعلى نحو مخصوص، يتمايز عن التنظيم العام للتظلم من أعمال القاضي التي لا تعتبر أحكاما قضائية، كالأوامر على عرائض مثلا."},{"kind":"text","text":"سوف نتبين أولا جوانب التمايز هذه، قبل أن نتعرض للقرارات القابلة للتظلم."},{"kind":"heading","text":"المطلب الأول: خصوصيات التظلم من قرارات قاضي التنفيذ"},{"kind":"text","text":"440- التظلم- والمقابل للطعن- هو طريق لمراجعة الأعمال الولائية كالأوامر على عرائض والقرارات. ويختلف التنظيم القانوني للتظلم من قرارات قاضي التنفيذ عن التنظيم العام المقرر للتظلم من الأوامر على عرائض من عدة نواح:"},{"kind":"text","text":"فمن ناحية أولى، فالأصل أن الاختصاص بنظر التظلم من الأعمال التي تصدر من القاضي- أي قاض- ولا تعتبر حكما، وأشهرها الأوامر على عرائض، هو للقاضي نفسه الذي أصدر الأمر. ولكن خرج المشرع على هذا الأصل فيما يتعلق بالتظلم من بعض قرارات قاضي التنفيذ، وجعل الاختصاص بنظره لقاض آخر غير مصدر القرار، هو رئيس المحكمة أو من يفوضه (مادة 1- 209 فقرة أخيرة)."},{"kind":"text","text":"ومن ناحية ثانية، الأصل أن الطريق الإجرائي للتظلم من الأعمال التي لا تعتبر حكما، هو طريق الدعوى القضائية وما يعقب رفعها من خصومة. ولكن- وللمرة الثانية- يخرج المشرع على هذا الأصل ويجعل التظلم من قرارات قاضي التنفيذ بغير طريق الدعوى. إذ يتم التظلم هنا بموجب \" طلب يودع في ذات ملف التنفيذ \" (مادة 1-209 فقرة أخيرة). ولا شك أن الاكتفاء بهذه العبارة يفيد عدم الحاجة إلى إعلان الطرف الآخر وعدم وجود جلسة مرافعة، أي عدم وجود خصومة قضائية. ويؤكد هذا المعنى النص في المادة المذكورة على نظر التظلم من جانب القاضي المتظلم أمامه \"دون حاجة لدعوة الخصوم ما لم ير ضرورة لذلك\"."},{"kind":"text","text":"ومن ناحية ثالثة، واتساقا مع ما سبق، فالأصل أن ما يصدر في التظلم عموما هو حكم قضائي بمعنى الكلمة نظرا لصدوره في خصومة، وأن هذا الحكم يقبل الطعن فيه بعد ذلك بطرق الطعن المقررة. ولكن يخرج المشرع -وللمرة الثالثة- على هذا الأصل، ويعتبر أن ما يصدر في التظلم من قرارات قاضي التنفيذ من تأييد لها أو تعديل أو إلغاء، قرار هو الآخر وليس حكما قضائيا. والذي يجعل هذه النتيجة منطقية، أن التظلم من قرارات قاضي التنفيذ لم تنشأ عنه أصلا خصومة. وفضلا عما سبق، أراد المشرع أن يكون القرار الصادر في التظلم هنا نهائيا غير قابل للطعن (مادة 1-209 فقرة أخيرة). من الواضح إذا رغبة المشرع في تصفية ما ينشأ عن عملية التنفيذ من اعتراضات، في وقت قصير."},{"kind":"text","text":"ومن ناحية رابعة، فالأصل أن التظلم من العمل الولائي الذي لا يعتبر حكما ليس له ميعاد محدد. فالأوامر على عرائض مثلا تقبل التظلم منها دون التقيد بميعاد محدد. ولكن يأتي المشرع وينص على خلاف ذلك فيما يتعلق بالتظلم من قرارات قاضي التنفيذ. فقد جعل له ميعادا محددا هو سبعة أيام (مادة 1-209 فقرة أخيرة)."},{"kind":"text","text":"ومن ناحية خامسة وأخيرة، يجوز بحسب الأصل وبمناسبة التظلم من القرار الذي لا يعتبر حكما، أن يقوم القاضي الذي ينظر التظلم بوقف تنفيذ هذا القرار مؤقتا لحين الفصل في التظلم، والذي قد يتراخى لبعض الوقت. ولم يتضمن النص الذي ينظم التظلم من قرارات قاضي التنفيذ ما يفيد خضوعه لهذا الأصل. السبب في ذلك هو عدم الحاجة إلى الوقف هنا لحين الفصل في التظلم، نظرا لعدم خضوعه لنظام الخصومة وما تستغرقه من وقت."},{"kind":"heading","text":"المطلب الثاني: دراسة تفصيلية لقرارات قاضي التنفيذ القابلة للتظلم"},{"kind":"text","text":"تحصر المادة 1- 209 قرارات قاضي التنفيذ القابلة للتظلم في سبعة هي ما يأتي:"},{"kind":"text","text":"(أ) ترتيب الأفضلية بين الحاجزين أو إدراجهم من عدمه في قائمة التوزيع"},{"kind":"text","text":"441- سبق أن رأينا أنه عند الوصول إلى مرحلة توزيع حصيلة التنفيذ، فإنه إذا لم تكن حصيلة التنفيذ كافية للوفاء بحقوق جميع الحاجزين، يعد قاضي التنفيذ قائمة توزيع مؤقتة يسمي فيه الدائنين المستحقين لأنصبتهم من حصيلة التنفيذ ومقدار هذه الأنصبة بحسب ترتيب أفضليتهم وفقا للقانون الموضوعي. وعلى ضوء الاعتراضات المقدمة، يعد قاضي التنفيذ قائمة توزيع نهائية بما يستحق كل دائن. وعلى قاضي التنفيذ وهو يعد هذه القائمة أو تلك أن يراعى أفضلية بعض الدائنين على البعض الآخر بالنظر إلى الترتيب المحدد قانونا لكل دائن ممتاز أو صاحب حق مقيد، وبالنظر إلى تقدم أي من هؤلاء على الدائن العادي، وكذلك بالنظر لتقدم بعض الدائنين العاديين أحيانا على بعضهم البعض."},{"kind":"text","text":"وقد تكون لأحد ذوي الشأن مصلحة في التظلم مما ورد في أي من القائمتين المذكورتين، والتي تعد قرارا من قرارات قاضي التنفيذ، سواء لعدم إدراجه في القائمة أو لعدم حصوله على المرتبة التي يستحقها."},{"kind":"text","text":"فهل معنى ذلك أن قرار الإدراج أو عدم الإدراج أو ترتيب الأفضلية الذي تتضمنه القائمة المؤقتة أو القائمة النهائية هو من القرارات التي تقبل التظلم وفقا للمادة 1-209 فقرة أخيرة، والتي أجازت التظلم في قرارات قاضي التنفيذ المتعلقة بترتيب الأفضلية بين الحاجزين أو إدراجهم من عدمه في قائمة التوزيع؟"},{"kind":"text","text":"442- الحقيقة أن التوفيق بين النصوص يستلزم منا ضرورة التفرقة بين القرارين السابقين المتعلقين بترتيب الأفضلية والإدراج من عدمه، وأن أحد هذين القرارين فقط هو الذي يخضع للتظلم منه وفقا للتنظيم الذي تتضمنه المادة 1- 209، وهو قرار ترتيب الأفضلية أو الإدراج الذي يظهر في قائمة التوزيع \"النهائية\"."},{"kind":"text","text":"أما قرار الإدراج أو ترتيب الأفضلية الذي يظهر في قائمة التوزيع المؤقتة، فإن مراجعته لن تكون خاضعة للتنظيم الوارد في المادة 1-209 دون غيره. إذ أن هناك نظاما آخر للتظلم من الإدراج أو ترتيب الأفضلية بين الحاجزين في قائمة التوزيع المؤقتة، يسمى بالاعتراض على قائمة التوزيع، تتضمنه المادة 313. ولعل من أبرز ما يميز هذا الطريق من طرق المراجعة -بالمقارنة مع نظام تظلم المادة 1- 209- أنه يتوافق مع الأصل العام في التظلم، بالنظر إلى أنه يكون أمام قاضي التنفيذ ذاته. ولقد انتهينا إلى أنه يجوز للحاجز التظلم من قرار ترتيب الأفضلية إما وفقا للمادة 1-209 أو وفقا للمادة 313."},{"kind":"text","text":"(ب) تأجيل التنفيذ لأي سبب"},{"kind":"text","text":"443- هناك أسباب قانونية عديدة لتأجيل التنفيذ. نقابل ذلك بصورة واضحة في النصوص التي تعطي لقاضي التنفيذ سلطة إصدار قرارات بإرجاء بيع العقار المحجوز في عدة أحوال. ولكن بجانب هذه الأسباب، لا يوجد ما يمنع من تمتع قاضي التنفيذ بسلطة تأجيل التنفيذ لأي سبب، انطلاقا من سلطته في الإشراف على التنفيذ."},{"kind":"text","text":"وتأجيل التنفيذ يختلف عن وقفه. يكفي أن الوقف لا يعرف معه مقدما وعلى وجه القطع التاريخ الذي يستأنف فيه التنفيذ، بعكس التأجيل. هذا فضلا عن اختلاف أسباب التأجيل عن أسباب الوقف."},{"kind":"text","text":"وقد يصدر قرار بتأجيل التنفيذ على نحو يمس بمصلحة أحد ذوي الشأن، كما لو أصدر قاضي التنفيذ قرارا بالتأجيل في حالة مغايرة لتلك التي قد تكون محددة قانونا، أو كان التأجيل لمدة أطول أو أقصر مما ينبغي قانونا، أو لمدة يراها صاحب الشأن غير ملائمة. ولذلك كان طبيعيا أن يتيح المشرع التظلم من هذا القرار، ووفقا للإجراءات والمدد المنصوص عليها في المادة 1- 209."},{"kind":"text","text":"444- وتجب ملاحظة أن التظلم يكون من قرار التأجيل تحديدا وليس من عموم القرارات الصادرة بشأن التأجيل. وبناء عليه، فإن القرار الصادر من قاضي التنفيذ برفض طلب التأجيل لا يقبل التظلم."},{"kind":"text","text":"(ج) إعطاء المدين مهلة للدفع أو تقسيط المبلغ المنفذ من أجله"},{"kind":"text","text":"445- يمكن العثور على هذا القرار بمناسبة الطلب المقدم إلى قاضي التنفيذ من الدائن بحبس مدينه. ففي هذا الفرض، يجوز لقاضي التنفيذ أن يأمر بالحبس، أو أن يقرر قبل إصداره هذا الأمر -وبناء على طلب من المدين- أن يمنحه مهلة للوفاء لا تجاوز ستة أشهر متتالية، أو تقسيط المبلغ المنفذ من أجله على أقساط مناسبة لا تجاوز ثلاث سنوات (مادة 320)."},{"kind":"text","text":"والقرار الصادر هنا بإعطاء مهلة للمدين أو تقسيط المبلغ، يقبل بنص صريح التظلم الذي تنظمه المادة 1- 209، خاصة وأن المادة 3- 320 تؤكد على نفس هذا المعنى."},{"kind":"text","text":"ولذلك يجوز التظلم لمجرد أن القرار أعطى للمدين مهلة أو َقبل تقسيط المبلغ، أو كانت المهلة المعطاة للمدين تتجاوز الستة أشهر أو أعطيت له متقطعة وليس دفعة واحدة، أو كان التقسيط لمدة تتجاوز الثلاث سنوات أو كانت الأقساط غير مناسبة."},{"kind":"text","text":"446- ويلاحظ أن الذي يقبل التظلم هو القرار الإيجابي، أي الصادر بإعطاء المهلة أو بتقسيط المبلغ. أما القرار الصادر برفض إعطاء مهلة أو برفض التقسيط، أو جعل مهلة الدفع أو التقسيط قصيرة، فهو لا يقبل التظلم."},{"kind":"text","text":"447- على أنه بالإضافة إلى هذه الحالة المنصوص عليها صراحة في خصوص الحبس، فإنه لا مانع في نظرنا من أن تكون لقاضي التنفيذ بمقتضى سلطته الإشرافية سلطة إصدار قرار بمنح مهلة للمدين أو تقسيط المبلغ بمناسبة أية معاملة تنفيذية تجري تحت إشرافه، على أن يكون منح المهلة أو التقسيط بناء على طلب مقدم من المنفذ ضده. وعندئذ يجب في نظرنا إخضاع هذا القرار للتظلم الذي يخضع له القرار الذي نحن بصدده الآن، والذي تنظمه المادة 1- 209-ج."},{"kind":"text","text":"(د) قبول الكفالة من عدمه"},{"kind":"text","text":"448- للكفالة تطبيقات متعددة في مجال التنفيذ الجبري. وتدخل بعض هذه التطبيقات في اختصاص قاضي التنفيذ. وهو يمارس اختصاصه هذا في عدة مناسبات من خلال القرار. من ذلك حالة إرجاء بيع العقار المحجوز لوجود إيرادات تكفي لسداد الدين خلال مدة لا تزيد على خمس سنوات، إذ لقاضي التنفيذ هنا إصدار قرار الإرجاء بالضمانات التي يراها (مادة 2- 288- ب). من ذلك أيضا حالة الكفالة المقدمة من أحد البنوك لكي تقوم مقام إيداع كامل الثمن خزينة المحكمة من جانب من رسا عليه المزاد عند بيع العقار المحجوز(مادة5-297)، وحالة الضمانات التي يقدرها قاضي التنفيذ إذا كان يخشى هروب المدين خارج الدولة وقرر مع ذلك تقسيط المبلغ المنفذ من أجله بدلا من أن يصدر أمر الحبس (مادة 2- 320)، وحالة الكفالة المصرفية أو الكفيل المقتدر الذي يقبله قاضي التنفيذ للوفاء بالدين والتي يقدمها المدين لكي يمتنع إصدار أمر الحبس(مادة1- 321-د)، وحالة الكفالة التي يقدمها الدائن كأحد شروط إصدار أمر بمنع مدينه من السفر في بعض الأحوال(مادة 1-324-ب)، وحالة الكفالة المصرفية الكافية أو الكفيل المقتدر الذي يقبله القاضي والتي يقدمها المدين لكي يسقط الأمر الصادر بمنعه من السفر(مادة 3-325)."},{"kind":"text","text":"في كل هذه الأحوال، يكون قرار قاضي التنفيذ بقبول الكفالة من عدمها قابلا للتظلم منه وفقا للإجراءات والمدد المحددة في المادة 1- 209."},{"kind":"text","text":"(ه) المنع من السفر أو رفض الأمر به"},{"kind":"text","text":"449- الأصل أن الأمر بمنع المدين من السفر لا يصدر من قاضي التنفيذ، وأنه يأخذ شكل الأمر على عريضة، ويقبل التظلم منه وفقا للقواعد العامة، أي للإجراءات المقررة للتظلم من الأوامر على عرائض."},{"kind":"text","text":"450- وخروجا على هذا الأصل، توجد بعض الحالات الاستثنائية التي يكون فيها مصدر الأمر بمنع المدين من السفر هو قاضي التنفيذ المختص. وعندئذ سيكون التظلم من قراره خاضعا لما هو مقرر في المادة 1- 209 – ه."},{"kind":"text","text":"الحالة الأولى من هذه الحالات وردت في المادة 3- 234. فالمستفاد من هذه المادة أن لكل دائن معه سند تنفيذي وتقدم لقاضي التنفيذ بطلب التنفيذ على أموال مدينه، أن يطلب منه أيضا منع المنفذ ضده من السفر حتى قبل إعلانه بالسند التنفيذي، وأن لقاضي التنفيذ أن يأمر بالمنع إذا تبين له ما يشير إلى سعي المدين لمغادرة الدولة"},{"kind":"text","text":". والحالة الثانية هي حالة اختصاص قاضي تنفيذ الأحوال الشخصية وحده دون غيره بإصدار أوامر المنع من السفر في مسائل الأحوال الشخصية (مادة 227)، بما في ذلك منع المحضون من السفر (مادة 3-324)."},{"kind":"text","text":"451- ويلاحظ أن التظلم من قرارات قاضي التنفيذ المتعلقة بالمنع من السفر لا يقتصر على القرار الصادر بالمنع، وإنما يمتد ليشمل أيضا القرار الصادر برفض الطلب. السند في ذلك مستمد بسهولة من نص المادة 1-209 والتي تذكر صراحة كلا القرارين، وكذلك المادة 4-324 المنظمة للتظلم من الأوامر الصادرة بشأن المنع من السفر بصفة عامة. فقد أجازت هذه المادة صراحة التظلم ممن صدر أمر بمنعه من السفر وكذلك ممن رفض طلبه. وهي ذاتها التي أشارت إلى أن التظلم في هذه الحالة أو تلك خاضع للمادة 1-209 إذا كان القرار صادرا من قاضي التنفيذ."},{"kind":"text","text":"(و) أمر الضبط والإحضار أو رفض الأمر به"},{"kind":"text","text":"452- الأصل أن أوامر الضبط والإحضار إنما تصدر من النيابة العامة ولا شأن لقاضي التنفيذ -أو للقاضي المدني عموما -بها. لكن هذا الأصل لا يمنع من وجود استثناءات عليه قررتها النصوص أو جرى عليها العمل، بحيث صار جائزا أن يصدر من قاضي التنفيذ أمر ضبط وإحضار. ويكفي لتأكيد هذا المعنى أن النصوص تناولت ذلك في أكثر من مناسبة، ومنها نص المادة 1- 209. فقد ذكرته ضمن ما ذكرته من قرارات قاضي التنفيذ القابلة للتظلم. فلو كان قاضي التنفيذ عديم الصلة به، ما ثارت الحاجة إلى هذا التنظيم."},{"kind":"text","text":"453- والمناسبة الأولى لتصور وجود اختصاص لقاضي التنفيذ بإصدار أمر ضبط وإحضار، هي الحالتان الاستثنائيتان اللتان يكون فيهما الأمر بمنع المدين من السفر صادرا من قاضي التنفيذ، وكان هذا الأمر يتضمن إلزام المدين بتسليم جواز سفره وامتنع عن ذلك دون مبرر، أو تبين أنه قد تصرف في أمواله أو هربها أو أنه يعد العدة للفرار خارج الدولة. ففي أي من هذه الأحوال، يجوز للدائن الرجوع إلى قاضي التنفيذ الذي أصدر الأمر، والذي يمكنه أن يأمر بضبط المدين وإحضاره وإلزامه بتقديم كفالة أو إيداع المبلغ المدعى عليه به خزانة المحكمة (مادة 327)."},{"kind":"text","text":"وأمر الضبط والإحضار هذا وما تضمنه من وجوب تقديم كفالة أو إيداع، يخضع لحكم المادة 1- 209، ويقبل بالتالي التظلم وفقا لها."},{"kind":"text","text":"454- أما المناسبة الثانية، فهي حالات لا تقع تحت حصر ويجري العمل عليها. من ذلك مثلا الحالة التي يتقدم فيها الدائن إلى قاضي التنفيذ -ومن خلال نظام الأمر على عريضة- بطلب حبس المدين الممتنع عن تنفيذ السند التنفيذي. إذ يجري العمل أحيانا بأن يأمر هذا القاضي بضبط وإحضار المدين للوقوف على حاله، أي يسره أو عسره.. في هذه الحالة أيضا وما يماثلها يجوز التظلم من أمر الضبط والإحضار وفقا للمادة 1- 209."},{"kind":"text","text":"(ز) وقف التنفيذ"},{"kind":"text","text":"455- ما سبق من قرارات لقاضي التنفيذ تقبل التظلم، كان يقتصر على تلك القرارات التي وردت في المادة 1-209. ولكن يجب أن يضاف إليها ما جاء في نصوص أخرى من قرارات تصدر من هذا القاضي وذكرت أن التظلم منها يكون بنفس الإجراءات السابق التعرف عليها."},{"kind":"text","text":"أبرز هذه القرارات الأخرى هو القرار الصادر في طلب وقف التنفيذ -والمسمى بالإشكال الوقتي في التنفيذ – والذي تناولته المادة 239."},{"kind":"heading","text":"المبحث الثالث: عدم قابلية باقي القرارات للمراجعة"},{"kind":"text","text":"471- فالمستفاد من نص المادة 209 - وهي المادة الأساس في طرق مراجعة قرارات قاضي التنفيذ- أن بعض هذه القرارات قابلة للتظلم منها، وبعضها قابلة للطعن بالاستئناف. وفيما عدا هذه أو تلك يكون القرار الصادر من قاضي التنفيذ غير قابل للمراجعة، إلا إذا وجد نص خاص يقرر خلاف ذلك."},{"kind":"text","text":"وبناء عليه فإن قرار الحجز في ذاته لا يجوز التظلم منه أو استئنافه لعدم دخوله في القرارات التي نصت عليها المادة 209. ولذلك فإنه إذا حدث وتم استئنافه، فإنه يجب الحكم بعدم القبول. أما إذا أخطأت المحكمة وأصدرت حكما في الموضوع، فإن حكمها هذا يعتبر صادرا في إجراء تنفيذي بحت لا يجوز الطعن عليه بالنقض، نزولا على مقتضي البند 3 من المادة 175 من القانون."},{"kind":"text","text":"لكن يمكن القول بأنه يجوز رفع دعوى تنفيذ موضوعية بطلب بطلان القرارات التي لا تقبل التظلم أو الاستئناف، وكذلك طلب بطلان التنفيذ المترتب عليها."},{"kind":"text","text":"وكذلك يجوز رفع دعوى وقتية (إشكال وقتي بطلب وقف التنفيذ) بصددها. إذ توجد مصلحة قانونية لطلب الوقف طالما أن القرار ذاته يقبل الإلغاء إذا كان القرار منعدما أو باطلا ويرتب بالتالي بطلان التنفيذ."},{"kind":"heading","text":"الفصل الثاني: الأوامر على عرائض"},{"kind":"text","text":"472- يصدر قاضي التنفيذ أوامر قضائية تتعلق بالتنفيذ، وتأخذ شكل الأوامر على عرائض. هذه الأوامر تختلف بالتأكيد عن الأحكام القضائية. يكفي أن هذه الأخيرة تصدر في خصومة بينما الأوامر على عرائض تصدر بغير خصومة."},{"kind":"text","text":"وفي المقابل تقترب الأوامر على عرائض من القرارات. إلا أنه يظل التمييز بينهما ممكنا. فالقرارات هي ما يصدر من حيث المبدأ من تلقاء نفس القاضي، بينما الأوامر هي ما يصدر منه بناء على عريضة مقدمة إليه من ذي شأن وفقا لنظام الأوامر على عريضة،"},{"kind":"text","text":"ولا شك في أهمية التفرقة بين القرار والأمر على عريضة. يكفي أن كلا منهما يخضع لطرق مراجعة خاصة به. فبينما مراجعة القرار -وكما سبق ورأينا- تتم من خلال التظلم أو الاستئناف بحسب الأحوال، فإن مراجعة الأمر على عريضة تتم فقط من خلال نظام التظلم، ومع وجود اختلاف كبير بين النظام الإجرائي للتظلم من القرار ومثيله المقرر للتظلم من الأمر."},{"kind":"text","text":"وسبق لنا التعرف على أهم الأوامر على عرائض التي تصدر من قاضي التنفيذ بمناسبة دراسة وظيفته الولائية. ونضيف إليها الآن الأمر بتنفيذ الأحكام أو غيرها من السندات الأجنبية."},{"kind":"text","text":"إذ يطلب الأمر بتنفيذ الحكم الصادر من بلد أجنبي- أو غيره من السندات الأجنبية- بعريضة تقدم لقاضي التنفيذ، ويصدر الأمر بالتنفيذ-أو برفضه- على العريضة، خلال خمسة أيام عمل على الأكثر من تاريخ تقديمها، ويكون هذا الأمر قابلا للاستئناف مباشرة وفقا للقواعد والإجراءات المقررة لاستئناف الأحكام (مادة 2-222)."},{"kind":"text","text":"وأوجه الخصوصية في هذا الشأن متعددة. فمن ناحية أولى، رغم أننا أمام عمل قضائي يصدر في شكل أمر على عريضة، إلا أن طريق مراجعة هذا الأمر ليس هو التظلم لقاضي التنفيذ الذي أصدره كما هي القاعدة العامة بشأن الأوامر على عرائض طبقا للمادة 141، ولا حتى التظلم لرئيس المحكمة كما هي القاعدة المقررة بشأن التظلم من قرارات قاضي التنفيذ القابلة للتظلم طبقا للمادة 1- 209، وإنما هي الطعن بالاستئناف، رغم أن هذا الطعن مقرر أساسا للأحكام القضائية وليس للأوامر."},{"kind":"text","text":"ومن ناحية ثانية، فإن إجراءات الطعن بالاستئناف في الأمر على العريضة الصادر بشأن تنفيذ الحكم أو غيره من السندات الأجنبية، ليست كما هي العادة إجراءات استئناف قرارات قاضي التنفيذ القابلة للاستئناف والمقررة في المادة 209 -2، والتي تنطوي على بعض الخصوصيات، وإنما هي إجراءات الاستئناف العادية المقررة للأحكام. ولذلك فإن ميعاد الاستئناف سيكون 30 يوما، ويمكن طلب وقف التنفيذ، والحكم الصادر في الاستئناف يقبل الطعن عليه بطريق النقض."},{"kind":"heading","text":"الفصل الثالث: الأحكام القضائية"},{"kind":"text","text":"453- عديدة هي الوسائل التي يمارس بها قاضي التنفيذ وظائفه. فقد تعرفنا فيما سبق على وسيلتين هما القرارات والأوامر. وهما يظهران بمناسبة وظيفته الإشرافية على سير إجراءات التنفيذ. والعملية الإجرائية التي يصدر بمناسبتها هذان العملان هي إجراءات التنفيذ، وهي لا تشكل خصومة قضائية بالمعنى الفني الدقيق. فعبارة خصومة التنفيذ التي يطلقها البعض على إجراءات التنفيذ لا تغير من هذه الحقيقة. ذلك لأن الخصومة القضائية لا تظهر في مجال التنفيذ إلا إذا أثيرت منازعة تتعلق بالتنفيذ. فعندما ترفع دعوى قضائية أمام قاضي التنفيذ، فعندئذ- وعندئذ فقط- تنشأ خصومة قضائية بمعنى الكلمة. وحينها ستظهر وسيلة ثالثة- تضاف إلى القرارات والأوامر- يمارس بها قاضي التنفيذ وظيفته القضائية هذه المرة، وهذه الوسيلة هي الحكم القضائي. فالقاعدة المستقرة أن الحكم القضائي هو ما يصدر من القاضي- ولو كان قاضي التنفيذ- في خصومة قضائية."},{"kind":"text","text":"وأهمية التعرف على الحكم القضائي الذي يصدر من قاضي التنفيذ، أنه يتمايز عن كل من القرارات والأوامر، من أن له حجية الأمر المقضي فيه، ومن أن وسيلة مراجعته العادية هي طريق الطعن بالاستئناف، دون الحاجة إلى نص خاص يقررها."},{"kind":"text","text":"ودراستنا للحكم القضائي التنفيذي-إن جاز التعبير- ستكون بطبيعة الحال من خلال دراسة منازعات التنفيذ."},{"kind":"heading","text":"المبحث الأول: اختصاص قاضي التنفيذ بمنازعات التنفيذ"},{"kind":"text","text":"454- منازعات التنفيذ قد تكون وقتية وقد تكون موضوعية. وليس هناك أي شك حول اختصاص قاضي التنفيذ بالمنازعات الوقتية المتعلقة بالتنفيذ، فالمادة 207 من القانون أدخلت هذه المنازعات بنص قطعي الدلالة في اختصاص قاضي التنفيذ."},{"kind":"text","text":"على أنه لم يعد لدراسة الحكم القضائي الذي يصدر في هذا النوع من المنازعات أهمية كبيرة من الناحية العملية. فأهم منازعات التنفيذ الوقتية هي طلب وقف التنفيذ مؤقتا أو ما يشاع تسميته بالإشكال الوقتي. وهذا الأخير صار الفصل فيه اليوم من خلال نظام العريضة وليس من خلال الخصومة القضائية، وما يصدر فيه أمر أو قرار وليس حكما قضائيا."},{"kind":"text","text":"455- أما إذا بحثنا عن الحكم القضائي الذي يصدر في المنازعات الموضوعية المتعلقة بالتنفيذ، فإننا نجده بسهولة حين يصدر من محاكم الموضوع- ونقصد بذلك المحاكم الأخرى غير قاضي التنفيذ- والتي جعلها المشرع- وبمقتضى نصوص صريحة - مختصة ببعض هذه المنازعات. ينطبق ذلك مثلا على ما يصدر في دعوى استرداد الأشياء المحجوزة أو دعوى استحقاق العقار المحجوز."},{"kind":"text","text":"456- ولكن هل يجوز أيضا إصدار حكم من قاضي التنفيذ في منازعات التنفيذ الموضوعية الأخرى؟ سوف نتعرف على ذلك من خلال دراستنا لهذه المنازعات حالا."},{"kind":"heading","text":"المبحث الثاني: ماهية منازعات التنفيذ"},{"kind":"heading","text":"457- منازعات التنفيذ هي تلك التي تثور بمناسبة التنفيذ الجبري، وتتعلق بسيره أو بصحته."},{"kind":"text","text":"ذلك لأن للتنفيذ الجبري أركان يجب توافرها، وإجراءات يجب اتباعها. فإذا جرى تنفيذ بالمخالفة لأي من ذلك، كان لابد أن تتاح لذوي الشأن - خاصة المنفذ ضده- مكنة المنازعة في هذا التنفيذ، توصلا إلى إيقافه ثم إبطاله."},{"kind":"text","text":"فمنازعة التنفيذ قد تكون منازعة وقتية (أو مستعجلة)، وذلك عندما تستهدف مجرد سير التنفيذ (خاصة وقفه أو استمراره أو عدم الاعتداد به)، وقد تكون منازعة موضوعية، وذلك عندما تستهدف بطلان التنفيذ."},{"kind":"text","text":"458- أما مجرد اتصال المنازعة بالتنفيذ وإثارتها أثناءه، فهذا لا يكفي لاعتبارها من منازعات التنفيذ، طالما لا تتعلق بسير التنفيذ أو بطلانه. فدعوى ثبوت الحق مثلا التي ترفع بمناسبة الحجز التحفظي أو حجز ما للمدين لدى الغير، ليست من منازعات التنفيذ، لأنها لا تتعلق بصحة الحجز."},{"kind":"text","text":"459- أيضا لا يعتبر التظلم من وصف الحكم أو الطعن فيه من منازعات التنفيذ. على أنه يمكن إثارة انعدام السند التنفيذي أمام قاضي التنفيذ. فلو تبين مثلا أن الحكم سند التنفيذ منعدما لصدوره ضد شخص توفى قبل رفع الدعوى، جاز طلب الوقف من قاضي التنفيذ، لحين الحصول على حكم بانعدامه بدعوى بطلان أصلية ترفع أمام المحكمة المختصة (المحكمة التي أصدرته من حيث المبدأ)."},{"kind":"text","text":"460- أيضا لا يجوز اعتبار طلب تفسير الحكم سند التنفيذ أو تصحيح الخطأ المادي المنسوب إليه منازعة تنفيذ ولو أثير ذلك بمناسبة التنفيذ. ذلك أن قاضي التنفيذ تنحصر مهمته في تنفيذ منطوق الحكم القضائي إذا كان هو السند التنفيذي. فإذا شاب منطوق الحكم غموض أو إبهام أو لحق به خطأ يتطلب تنفيذه تفسيرا أو توضيحا لذلك، تعين على أي من الخصوم تكون له مصلحة في ذلك أن يعود إلى المحكمة التي أصدرت الحكم لتصحيح الخطأ أو تفسير الغموض والإبهام."},{"kind":"text","text":"أيضا لا تعتبر منازعة تنفيذ تلك التي لا تحتاج إلى قرار قضائي- حكم أو أمر أو قرار قضائي- لحسمها."},{"kind":"text","text":"461- والغالب أن ترفع منازعة التنفيذ أثناء جريانه. لكن قد ترفع ولو قبل البدء فيه وبمجرد اتخاذ مقدمة من مقدماته، كما لو أعلن المدين بالسند وتم تكليفه بالوفاء ورأى أنه ليس سندا تنفيذيا أو أن الحق الثابت به قد انقضى. وفي المقابل قد ترفع منازعة التنفيذ بعد انقضائه. إذ لا مانع من رفع دعوى بطلان التنفيذ حتى بعد البيع وتوزيع الحصيلة."},{"kind":"text","text":"462- ومنازعة التنفيذ قد تكون وقتية أو موضوعية حسب طلبات المدعي. فإذا وقع حجز على أموال المدين، فله أن يرفع دعوى بطلب إلغاء الحجز. وفي هذه الحالة تكون منازعته في التنفيذ منازعة موضوعية. كما أن له أن يطلب الحكم له بعدم الاعتداد بالحجز لكونه ظاهر البطلان ومن ثم هو مجرد عقبة مادية- كما لو كان الحجز واقعا على مال لا يجوز الحجز عليه- وعندئذ تكون منازعته منازعة تنفيذ وقتية أو مستعجلة مما يختص به قاضي التنفيذ."},{"kind":"text","text":"463- والأصل أن منازعة التنفيذ- مثلها مثل أي منازعة قضائية- ترفع إلى القضاء المختص بها بطريق الدعوى، فتنشأ عنها خصومة، ويصدر فيها حكم قضائي. على أن هذا الأصل يمكن الخروج عليه، بحيث تثار المنازعة بغير طريق الدعوى، وبالتالي دون أن تنعقد خصومة، ودون صدور حكم. فقد يكون الأمر على العريضة أو القرار هو الوسيلة التي خصصها المشرع لتذليل عقبة من عقبات التنفيذ. ولعل التنظيم الجديد لإشكالات التنفيذ الوقتية لخير دليل على ذلك. فقد صار الطريق الذي رسمه القانون لوقف التنفيذ- وهو أشهر الإشكالات الوقتية- هو نظام الأمر على العريضة."},{"kind":"text","text":"464- والأصل أن يختص قاضي التنفيذ بالفصل في جميع منازعات التنفيذ. على أن هذا الأصل يمكن الخروج عليه أيضا. إذ نظل أمام منازعة تنفيذ إذا توافرت مفترضاتها السابقة، حتى ولو عهد المشرع الاختصاص بها لغير قاضي التنفيذ."},{"kind":"text","text":"465- والمقرر أنه يجوز الطعن بالاستئناف في الحكم الصادر في منازعات التنفيذ أيا كان القاضي أو المحكمة مصدر الحكم تطبيقا للقواعد العامة. كما من المقرر أيضا أنه يجوز الطعن بالنقض في الحكم الصادر بعد ذلك من محاكم الاستئناف في هذه المنازعات وفقا للقواعد العامة أيضا. على أنه يستثني من ذلك الأحكام الصادرة من محاكم الاستئناف في منازعة منصبة على إجراءات التنفيذ (مادة 175)."},{"kind":"text","text":"هذا الاستثناء من الأصل لا يجوز التوسع في تفسيره أو القياس عليه، مما مؤداه أن الأحكام الأخرى الصادرة في غير هذا النطاق يجب ألا تندرج في نطاق الأحكام الصادرة في موضوع الخصومة التي تنصب على إجراءات التنفيذ. ولعل أشهر تطبيقات الأحكام التي لا تعتبر صادرة في إجراءات التنفيذ، مثل الأحكام الصادرة في شأن قبول الدعوى أو الطعن أو الاختصاص، أو المتعلقة بمدى صلاحية السند المطلوب تنفيذه للتنفيذ بموجبه. هذا مع الأخذ في الاعتبار أن هناك من أحكام النقض من يدرك المعنى السابق إلا أنه لم يطبقه حق تطبيقه."},{"kind":"heading","text":"المبحث الثالث: منازعات التنفيذ الموضوعية"},{"kind":"text","text":"465- هي تلك التي يطلب فيها الحكم بحسم النزاع في أصل الحق. ويقصد بهذا الأخير الحق في التنفيذ الجبري. هي إذا تلك التي تستهدف الحكم بعدم جواز التنفيذ (أو بجوازه) أو ببطلانه (أو بصحته) (.هي تسمى أيضا بإشكالات التنفيذ الموضوعية."},{"kind":"text","text":"466- لعل أشهر هذه المنازعات وأكثرها وضوحا هي دعوى بطلان التنفيذ، وهي من اختصاص قاضي التنفيذ بطبيعة الحال. وإلى جوارها ولا يقل عنها شهرة دعوى استرداد الأشياء المحجوزة ودعوى استحقاق العقار المحجوز. هاتان الدعويان من منازعات التنفيذ بلا منازع، إلا أن المشرع عهد بالاختصاص بهما لغير قاضي التنفيذ. وسوف تتركز الدراسة في هذا المبحث عليهما."},{"kind":"heading","text":"المطلب الأول: دعوى استرداد الأشياء المحجوزة"},{"kind":"text","text":"ماهيتها"},{"kind":"text","text":"467- هي الدعوى المرفوعة من الغير على كل من الحاجز والمحجوز عليه، أثناء التنفيذ على المنقول- أي بعد الحجز وقبل البيع- بطلب استرداد المنقول المحجوز، استنادا إلى أنه مملوك لهذا الغير، وكذلك بطلب بطلان التنفيذ لوقوعه على مال غير مملوك للمحجوز عليه."},{"kind":"text","text":"الفرع الأول: الخصوم في دعوى الاسترداد"},{"kind":"text","text":"469- دعوى الاسترداد مثلها مثل أي دعوى لابد وأن ترفع من مدع على مدعى عليه. كل ما هنالك أن هذا الأخير يجب أن يكون اثنان وليس واجدا، كما أن المدعي يجب أن يكون من الغير. كل ذلك يتضح من العرض الآتي:"},{"kind":"text","text":"(أ) المدعي من الغير"},{"kind":"text","text":"السند في ذلك أن دعوى الاسترداد ترفع على أطراف التنفيذ، وبالتالي لا يعقل أن تكون مرفوعة من أحدهم، نظرا لأن الخصم لا يحمل صفة المدعي وصفة المدعى عليه عن ذات الطلب. وطالما أن المدعي ليس من أطراف التنفيذ، فإنه يعتبر بالتالي غيرا. هذا الغير هو كل من يدعي أن المال المحجوز مملوك له هو وليس للمدين."},{"kind":"text","text":"ويثور التساؤل بالنسبة للمحجوز لديه في حجز ما للمدين لدى الغير. فقد يتضمن أمر الحجز مالا معينا باعتباره مملوكا للمدين المحجوز عليه. هذا المال يعتبر محجوزا بمجرد إعلان هذا الأمر للمحجوز لديه. فهل يجوز لهذا الأخير وهو من الغير رفع دعوى الاسترداد على سند من أن هذا المال المحجوز مملوك له هو وليس للمحجوز عليه؟ أرى أنه يكفي أن يقوم المحجوز لديه بتجاهل أي ذكر لهذا المال عند التقرير بما في الذمة، دون الحاجة إلى رفع دعوى استرداد. على أنه يمكن أن تثور حقيقة ملكيته لهذا المال عند المنازعة في التقرير."},{"kind":"text","text":"(ب) المدعى عليهم متعددون"},{"kind":"text","text":"دعوى استرداد الأشياء المحجوزة هي من الدعاوى القليلة التي يوجب فيها القانون اختصام أشخاص معينين متعددين. فيجب اختصام كل من الحاجز والمحجوز عليه معا، كما يجب أيضا اختصام الحاجزين المتدخلين في الحجز إن وجدوا (مادة 280). وأهمية هذا الشرط أن الدعوى تكون غير مقبولة إذا لم يتم اختصام كل هؤلاء الأشخاص، وهو عدم قبول من النظام العام، بدليل أن على المحكمة أن تقضي به من تلقاء نفسها (مادة 280)."},{"kind":"text","text":"الفرع الثاني: الطلبات"},{"kind":"text","text":"470- قد يبدو لأول وهلة أن الدعوى محل البحث وقد سميت قانونا بدعوى استرداد الأشياء المحجوزة، لا تتضمن سوى طلب واحد صريح هو طلب استرداد المنقول المحجوز، أي إخراجه من الحجز وتسليمه للمدعي طالب الاسترداد."},{"kind":"text","text":"ومع ذلك فإن التدقيق في الأمر يجب أن ينتهي بنا إلى نتيجة مختلفة، قوامها أن الدعوى محل البحث تنطوي على طلبين وليس طلبا واجدا، والمفارقة أن طلب الاسترداد الصريح ليس من بين هذين الطلبين."},{"kind":"text","text":"فالطلب الأول الذي يجعلنا أمام دعوى الاسترداد المنصوص عليها في المادة 279 وما بعدها هو طلب ثبوت ملكية المدعي للمال المحجوز. فالفرض أننا بصدد حجز وقع على مال منقول في حيازة المحجوز عليه واعتبر بالتالي مملوكا له طبقا لقرينة الحيازة في المنقول سند الملكية، وإن كانت قرينة تقبل إثبات العكس. وتهدف دعوى الاسترداد لإثبات هذا العكس، أي لإثبات ملكية المال المحجوز للمدعي وليس للمحجوز عليه."},{"kind":"text","text":"ولذلك يجب أن تنطوي صحيفة الدعوى على طلب الملكية ولو لم تتضمن طلب استرداد، إذ أن طلب الملكية ينطوي ضمنا على طلب استرداد. فمسألة الملكية -وليس الاسترداد- هي المسألة المتنازع عليها في حقيقة الأمر، وما طلب الاسترداد إلا من قبيل الملحقات."},{"kind":"text","text":"ومما يزيد من قناعتنا بأن طلب إثبات الملكية هو الطلب الرئيس في دعوى الاسترداد محل البحث، هو ضرورة اشتمال صحيفتها على بيان واف بأدلة الملكية وإلا كانت غير مقبولة (مادة 280)."},{"kind":"text","text":"471- أما الطلب الثاني الذي يجب أن تتضمنه صحيفة دعوى الاسترداد فهو طلب بطلان الحجز الواقع على المال المطلوب ثبوت ملكيته واسترداده. ذلك لأن هذا البطلان هو النتيجة الحتمية لثبوت ملكية الغير-وليس المحجوز عليه- للمال المحجوز، وطلب ثبوت الملكية هذا هو- كما سبق وأكدنا- هو الطلب الرئيس والحاضر دائما في دعوى الاسترداد. كما أن هذا البطلان هو الذي يبرر إخراج المال المطلوب استرداده من ربقة الحجز."},{"kind":"text","text":"ولذلك يمكن القول بوجود طلب ببطلان الحجز في كل دعوى استرداد أشياء محجوزة. فحتى إذا لم يكن هذا الطلب مذكورا صراحة في صحيفة الدعوى، فإنه يعتبر مطروحا كطلب ضمني. بل إن هذا الطلب هو الذي يجعل دعوى الاسترداد محل البحث من دعاوى التنفيذ الجبري، وبصرف النظر عن القضاء المختص بها، وبصرف النظر أيضا عن المقابلة بين نصوص دعوى الاسترداد ودعوى الاستحقاق."},{"kind":"text","text":"الفرع الثالث: شروط القبول"},{"kind":"text","text":"472- يشترط لقبول دعوى الاسترداد شروط القبول العامة-الإيجابية والسلبية- المطلوبة في الدعوى القضائية عموما. ولكن بالإضافة إلى ذلك، توجد بعض شروط القبول الخاصة بهذه الدعوى."},{"kind":"text","text":"ولقد تناولنا بالفعل شرطين من هذه الشروط الخاصة أحدهما يتعلق بالخصوم والآخر يتعلق بالطلبات."},{"kind":"heading","text":"473- ونضيف إليهما شرط ثالث هو ضرورة رفع الدعوى بعد الحجز وقبل البيع."},{"kind":"text","text":"الفرع الرابع: المحكمة المختصة"},{"kind":"text","text":"475- دعوى استرداد الأشياء المحجوزة هي دعوى موضوعية تتعلق بالتنفيذ الجبري بلا منازع. يكفي أن المطلوب فيها هو بطلان التنفيذ لعدم جواز الحجز على المال لكونه مملوكا لغير المحجوز عليه. كان من المتوقع إذا أن ينعقد الاختصاص بشأنها لقاضي التنفيذ تناغما مع اختصاصه الشامل من حيث المبدأ لكافة منازعات التنفيذ، ومع وضع النصوص الخاصة بها في الفصل الخاص بالحجوز."},{"kind":"text","text":"ومع ذلك نحى المشرع منحى آخر، حين نص في المادة 279 على أن “ترفع دعوى استرداد الأشياء المحجوز عليها أمام المحكمة المختصة..\"، مما مفاده أنها تخرج من اختصاص قاضي التنفيذ وتدخل في اختصاص محكمة الموضوع. ويقصد بمحكمة الموضوع هنا الدائرة الابتدائية طبقا لقواعد الاختصاص العامة- وتحديدا قواعد الاختصاص النوعي- وتقدر قيمتها لغايات الاستئناف ثم النقض طبقا لقيمة الأموال محل الحجز (مادة 8- 51). أما الاختصاص المكاني، فهو بالنظر لتعدد المدعى عليهم، ينعقد لمحكمة موطن أحدهم (مادة 4-33)."},{"kind":"text","text":"الحكمة من ذلك أن جوهر النزاع في هذه الدعوى، هو تحديد ما إذا كان مدعي الاسترداد هو المالك بالفعل للمال المحجوز أم لا، وما بطلان الحجز بعد ذلك أو عدم بطلانه سوى نتيجة تلقائية تترتب على بحث مسألة الملكية. ولما كان بحث هذه الأخيرة يدخل كأصل عام في اختصاص محكمة الموضوع وليس قاضي التنفيذ، لم يرد المشرع الخروج على هذا الأصل، حتى ولو أعقب ذلك أن تقضي محكمة الموضوع هذه في مسألة تبعية هي بطلان التنفيذ رغم أنها من مسائل التنفيذ، فالفرع يتبع الأصل وليس العكس."},{"kind":"text","text":"الفرع الخامس: الأثر الواقف للبيع المترتب على رفع الدعوى الأولى"},{"kind":"text","text":"476- الأصل أن رفع الدعوى-أي دعوى- لا يرتب آثارا بالنسبة للحق المطالب به، وأن هذه الآثار تترتب على الحكم الصادر فيها. وقد يخرج المشرع أحيانا على هذا الأصل. من ذلك أنه يترتب على مجرد رفع دعوى استرداد الأشياء المحجوزة وقف البيع (مادة 279)، وهو ما يعني تعطل الحق في التنفيذ. الحكمة من ذلك أن الحماية الموضوعية التي تستهدفها هذه الدعوى-وهي استرداد الغير لمنقوله المحجوز عليه خطأ- لن تتحقق إذا استمر التنفيذ وحصل البيع بالمزاد وصار المنقول المدعى بملكيته من جانب الغير في حوزة المشتري بالمزاد. فرغم أن البيع سيعتبر موقوفا لوقوعه على مال غير مملوك للمدين، إلا أن المحكوم له لن يستطيع أن يسترده من مشتريه وقد حازه بحسن النية ومن ثم صار مالكا له بمقتضى القرينة المنصوص عليها في المادة 1325 معاملات مدنية. ولذلك وحتى لا نصل إلى هذه النتيجة ارتأى المشرع وقف البيع فور رفع الدعوى، حتى يظل إخراج المال من الحجز ممكنا إذا ما صدر الحكم فيها بثبوت ملكية الغير له بالفعل."},{"kind":"text","text":"هذا الأثر الواقف للبيع لمجرد رفع دعوى الاسترداد قد يغري المحجوز عليه بأن يكرر، هو أو من يسخره، رفع الدعوى لمجرد الاستفادة من الوقف لبعض الوقت، حتى ولو حكم بعد ذلك بعدم قبولها أو برفضها. ولذلك لم يجعل المشرع الوقف حتميا في كل مرة ترفع فيها دعوى الاسترداد، وإنما على الدعوى الأولى فقط، كما أنه لم يجعله بالضرورة مستمرا طوال نظر الدعوى."},{"kind":"text","text":"(أ) لا يترتب الوقف بقوة القانون إلا على رفع دعوى الاسترداد الأولى"},{"kind":"text","text":"477- فعموم عبارة وقف البيع الواردة في المادة 279 لا تنصرف إلا للدعوى الأولى دون غيرها، بدلالة الإشارة المستقاة من المادة 146 والتي تقرر صراحة أن دعوى الاسترداد \"الثانية\" لا توقف البيع. رفع دعوى الاسترداد الثانية إذا لا يرتب أي أثر."},{"kind":"text","text":"478- والدعوى تعتبر ثانية حتى ولو رفعت من نفس طالب الاسترداد بعد أن انقضت خصومة دعواه الأولى، أيا كان سبب الانقضاء، أي حتى ولو انقضت دون الفصل في الموضوع."},{"kind":"text","text":"479- كما أن الدعوى تعتبر ثانية إذا رفعت منه، حتى ولو قبل انقضاء خصومة دعواه الأولى (مادة 2- 282). بل إن تجديد الدعوى الأولى من الشطب لن يعيد لها أثرها الواقف (مادة 1- 282)."},{"kind":"text","text":"480- أيضا تعتبر الدعوى ثانية إذا رفعت من مسترد آخر (مادة 2- 282) رغم أنها بمثابة دعوى أولى بالنسبة له. الحكمة من ذلك هي سد باب التحايل أمام المحجوز عليه حتى لا يسخر أكثر من شخص، بحيث يرفع كل منهم دعوى استرداد عقب زوال خصومة الدعوى التي رفعها غيره -أو حتى قبيل زوالها- من أجل جعل وقف البيع ممتدا."},{"kind":"text","text":"481- وفي النهاية تجدر الملاحظة أنه لا محل للحديث عن دعوى استرداد ثانية بالمعنى السابق إلا إذا كانت بخصوص نفس المنقولات المحجوزة التي رفعت عنها الدعوى الأولى. أما الدعوى التي ترفع بطلب استرداد منقولات أخرى غير تلك التي كانت محلا للدعوى الأولى، فإنها تعتبر دعوى أولى، سواء رفعت من نفس المسترد أم من مسترد آخر."},{"kind":"text","text":"(ب) للمحكمة التي تنظر الدعوى الأولى أن تحكم باستمرار التنفيذ"},{"kind":"text","text":"482- قد تكون دعوى الاسترداد دعوى أولى وترتب على رفعها بالفعل وقف للبيع بقوة القانون. فهل معنى ذلك أن يستمر هذا الوقف مترتبا حتما لحين زواله برفض الدعوى أو بانتهاء خصومتها بغير حكم في الموضوع؟ أجاب المشرع على هذا التساؤل بالنفي. فقد أعطى المحكمة التي تنظر الدعوى الأولى هذه أن تحكم باستمرار التنفيذ \".. بالشروط التي تراها مناسبة..\" (مادة 279). ومن أمثلة الشروط المناسبة – ونظرا للصياغة المرنة لهذه العبارة- أنه يجوز للمحكمة أن تشترط كفالة تحددها هي وليس المحكوم له. على أنه لا يجب إغفال ضرورة تقديم طلب باستمرار التنفيذ إلى المحكمة التي تنظر دعوى الاسترداد، إذ أنه شرط لا يحتاج إلى نص يقرره باعتبار أن ذلك من أصول التقاضي. والذي له الصفة المؤكدة في هذا الطلب هو أحد المدعى عليهم، وتحديدا الحاجز."},{"kind":"text","text":"(ج) للمحكمة التي تنظر الدعوى الثانية أن تحكم بوقف البيع"},{"kind":"text","text":"483- الفرض الآن أن دعوى الاسترداد اعتبرت دعوى ثانية وبالتالي لم يترتب على مجرد رفعها وقف البيع، فهل معنى ذلك حتمية استمرار التنفيذ؟ أجاب المشرع على هذا التساؤل بأن أعطى المحكمة التي تنظر دعوى الاسترداد الثانية- أو التي بعدها- سلطة الحكم بوقف البيع (مادة 1-282) لحين الفصل فيها. وبطبيعة الحال لابد أولا من طلب الوقف من ذي الصفة في ذلك، وهو المسترد."},{"kind":"text","text":"الفرع السادس: زوال الأثر الواقف للبيع المترتب على رفع الدعوى الأولى"},{"kind":"text","text":"484- سبق أن رأينا الحالات التي يقف فيها البيع بمناسبة دعوى الاسترداد. والمفروض أن يظل الوقف مترتبا إلى أن يزول سببه، بأن تنتهي الخصومة التي نشأت عن رفع هذه الدعوى. فإذا تحقق ذلك كان من حق الحاجز أن يمضي في التنفيذ."},{"kind":"text","text":"وبالفعل تساير المادة 1- 282 هذا المنطق. وزيادة في التأكيد قامت نفس المادة بتعداد لمختلف الأسباب التي تنقضي بها خصومة دعوى الاسترداد - والتي لا تختلف عن أسباب انقضاء أي خصومة – ورتبت على حدوث أي منها إمكانية المضي في التنفيذ، ويقصد بذلك تحديدا السير في إجراءات مرحلة البيع، فهي المرحلة التي كانت الإجراءات قد توقفت عندها. ولا صعوبة في أن يكون من هذه الأسباب المذكورة، الحكم باعتبار الدعوى-والأدق الخصومة- كأن لم تكن والحكم في الدعوى برفضها أو بعدم قبولها أو ببطلان صحيفتها أو بسقوط الخصومة فيها أو بقبول تركها."},{"kind":"text","text":"أما باقي الأسباب المذكورة، فهو يحتاج إلى تدقيق. أقصد بذلك تحديدا الحكم بشطب الدعوى والحكم بعدم الاختصاص."},{"kind":"text","text":"485- فبالنسبة لحكم الشطب، فالأصل المقرر قانونا أن الشطب لا ينهي الخصومة حتى ولو كانت خصومة دعوى الاسترداد. فالخصومة المشطوبة تظل قائمة ومرتبة لكل آثارها من قطع للتقادم وغيره. فكل ما يترتب على هذا الشطب هو استبعاد الدعوى من جدول القضايا المتداولة. كان من المتوقع إذا أن البيع الذي وقف نتيجة رفع دعوى الاسترداد يظل موقوفا رغم الشطب. إلا أن المشرع الذي قرر ما سبق، يملك أيضا أن يضع عليه ما يشاء من استثناءات. وبالفعل تتضمن المادة 281 -1 استثناء مفاده أن شطب خصومة دعوى الاسترداد يزيل الأثر الموقف للبيع ويسمح بالمضي في التنفيذ. ويبدو أن الحكمة من ذلك هي الحد من إساءة استعمال الحق في التقاضي."},{"kind":"text","text":"486- وبالنسبة لحكم عدم الاختصاص، فالأصل المقرر قانونا أيضا أن المحكمة التي أصدرته لا تكتفي به وإنما تقرر معه إحالة الدعوى إلى المحكمة المختصة. معنى ذلك أن دعوى الاسترداد التي صدر حكم بعدم الاختصاص بها من إحدى المحاكم سوف تظل قائمة أمام القضاء. كان من المتوقع إذا أن يظل الأثر الموقف للبيع مترتبا رغم صدور هذا الحكم. إلا أن المشرع خالف التوقعات وأتى باستثناء مفاده زوال الأثر الموقف هذا بمجرد الحكم بعدم الاختصاص. ويبدو أن العلة من هذا الاستثناء هي ذاتها التي كانت وراء الاستثناء الآخر والسابق الإشارة إليه."},{"kind":"text","text":"487- نعود الآن إلى مجمل الأحكام التي يترتب على صدورها في خصومة دعوى الاسترداد إمكانية المضي في التنفيذ. والمفروض أن مفعول هذه الأحكام – وهو زوال الأثر الواقف للبيع- يترتب بمجرد صدورها ولو كانت ابتدائية. والسند في ذلك أن هذا هو الأصل الحاكم لآثار الحكم القضائي عدا أثره التنفيذي. فترتيب الحكم لهذا الأثر الأخير هو فقط الذي يستلزم النهائية (أو الشمول بالنفاذ المعجل). أما إذا كان الحكم القضائي لا يمكنه بحسب \"مضمونه\" أن يرتب أي أثر تنفيذي (نظرا لكونه حكما مقررا وليس صادرا بإلزام، أو لكونه حكما إجرائيا وليس صادرا في الموضوع)، فصفة النهائية ليست مطلوبة فيه. وهذا ما ينطبق بالفعل على جميع الأحكام المذكورة في المادة 1- 281 سالفة الذكر والتي تنتهي بها خصومة دعوى الاسترداد. فهي في معظمها أحكام إجرائية، وحتى الحكم الموضوعي الوحيد المذكور فيها، أي الحكم الصادر برفض الدعوى، فهو حكم تقريري. ولذلك أراد المشرع التأكيد على هذا التصور حين قرر في البند الثاني من المادة أن الأحكام المذكورة ترتب مفعولها غير التنفيذي -أي زوال الأثر الواقف للبيع- ولو كانت قابلة للاستئناف."},{"kind":"text","text":"الفرع السابع: الحكم بالغرامة عند رفض دعوى الاسترداد"},{"kind":"text","text":"488- الأصل أن رفض الدعوى-أي دعوى- لا يعتبر بذاته قرينة على حصول تعٍد من جانب المدعي، مما يستوجب الحكم عليه بجزاء ما، وإنما يجعله فقط يتحمل مصاريف الدعوى. ولكن خرج المشرع على هذا الأصل، وأجاز للمحكمة وهي تفصل في دعوى الاسترداد أن تقضي بغرامة -وهي غرامة مدنية وليست عقوبة جزائية- لا تقل عن ألف درهم ولا تزيد على خمسة آلاف، في حال رفض الدعوى (مادة 279). الحكمة من هذا الاستثناء هي الحد من دعاوى الاسترداد الكيدية التي يكون القصد الحقيقي من ورائها مجرد تعطيل التنفيذ بالتواطؤ مع المحجوز عليه. وعلى ضوء هذه الحكمة يمكن القول بأن المشرع يجيز الحكم بالغرامة المذكورة فقط عند رفض دعوى الاسترداد الأولى، لأنها هي التي يترتب على رفعها وقف البيع بقوة القانون."},{"kind":"heading","text":"المطلب الثاني: دعوى استحقاق العقار المحجوز"},{"kind":"heading","text":"489- هي الدعوى المرفوعة ممن يدعي ملكيته لعقار محجوز، بقصد الحكم باستحقاق هذا العقار وبطلان الحجز الموقع عليه."},{"kind":"text","text":"وسوف نتناول دراسة هذه الدعوى من خلال الفروع التالية:"},{"kind":"text","text":"الفرع الأول: المحكمة المختصة"},{"kind":"text","text":"490- كان من الممكن أن تدخل دعوى الاستحقاق الفرعية في اختصاص قاضي التنفيذ بوصفها منازعة تتعلق بالتنفيذ. إذ لابد لرافعها أن يطلب بطلان إجراءات التنفيذ. وكان من الممكن أيضا أن تدخل هذه الدعوى في اختصاص محاكم الموضوع، لأنه لابد لرافعها أن يطلب أيضا ملكية العقار المحجوز، بل إن هذا الطلب هو الطلب الرئيس وما طلب بطلان التنفيذ سوى طلب متلازم."},{"kind":"text","text":"لذلك، فعندما أراد المشرع الاختيار بين قاضي التنفيذ وقاضي الموضوع، لم يكن مستغربا أن يضع في اعتباره أن مركز الثقل الحقيقي في الدعوى محل البحث هو طلب الملكية وليس البطلان، وبالتالي فإن الأحق بالاختصاص بها هو قاضي الموضوع. ولذلك تنص المادة 1-302 على أن ترفع هذه الدعوى أمام “المحكمة المختصة..\". مفاد ذلك إذا أن المشرع قد استثنى هذه الدعوى من المنازعات التي يختص بها قاضي التنفيذ، رغم النص العام المنظم لاختصاص قاضي التنفيذ- وهو المادة 207(بند1)- والذي يصرح بكونه مختصا بمنازعات التنفيذ الموضوعية."},{"kind":"text","text":"ولا توجد صعوبة بعد ذلك في تحديد محكمة الموضوع المختصة. فهي الدائرة الابتدائية، نظرا لاختصاصها النوعي بجميع الدعاوى الابتدائية (مادة 29)، أما الاختصاص المكاني أو المحلي فهو لمحكمة موقع العقار (مادة 1-34)، فنحن أمام دعوى عينية عقارية، نظرا لأن طلب ثبوت الملكية العقارية هو الطلب الرئيس في دعوى استحقاق العقار المحجوز."},{"kind":"text","text":"الفرع الثاني: الخصوم والطلبات"},{"kind":"text","text":"(أ) الخصوم"},{"kind":"text","text":"491- المدعي في دعوى استحقاق العقار المحجوز هو دائما من غير أطراف التنفيذ. فهو من يدعي أن العقار المحجوز عليه ملك له، وليس للمدين أو لمن في مركزه."},{"kind":"text","text":"492- أما المدعى عليه فهو يجب أن يكون متعددا. فدعوى الاستحقاق محل الدراسة هي من الدعاوى التي يوجب فيها القانون اختصام أكثر من شخص. إذ يجب اختصام كل من الحاجز (وهو الدائن، وكذلك من في حكمه من الدائنين أصحاب الحقوق المقيدة على العقار إن وجدوا)، والمحجوز عليه (وهو المدين، ومن في حكمه كالحائز أو الكفيل العيني بحسب الأحوال) (مادة 1- 302). ويترتب على عدم اختصام من يجب اختصامه من هؤلاء عدم قبول الدعوى، والذي يجب على المحكمة أن تقضي به ولو من تلقاء نفسها."},{"kind":"text","text":"(ب) الطلبات"},{"kind":"text","text":"493- لا تعتبر الدعوى محل البحث دعوى استحقاق مما تنظمه المادة 302 إلا إذا كانت متعلقة بالتنفيذ الجبري. والذي يجعلها كذلك أنها يجب أن تحتوي على طلبين أولهما طلب استحقاق العقار المحجوز عليه، أي طلب ثبوت ملكيته للمدعي، وثانيهما طلب بطلان إجراءات التنفيذ. أما الدعوى المتعلقة بملكية العقار ولا تتناول-ولو ضمنيا- طلب بطلان التنفيذ (كما لو كانت مرفوعة مثلا قبل الحجز)، فإنها لا تخضع لأحكام دعوى الاستحقاق محل البحث."},{"kind":"text","text":"الفرع الثالث: شروط القبول الخاصة"},{"kind":"text","text":"494- يجب بطبيعة الحال أن تتوافر في دعوى الاستحقاق شروط القبول العامة. بالإضافة إلى توافر شرطين آخرين خاصين بهذه الدعوى. فمن ناحية أولى، يجب اختصام الأشخاص المتعددين كما ذكرنا أنفا. ومن ناحية ثانية، يجب إيداع تأمين مقداره عشرة آلاف درهم عند قيد الدعوى (مادة 4-302). أما اشتمال صحيفة الدعوى على بيان دقيق لأدلة الملكية أو لوقائع الحيازة أو الاستحقاق التي تستند إليها الدعوى - وهو شرط نص عليه البند (1) من المادة آنفة الذكر وله ما يماثله في دعوى الاسترداد ويؤدي تخلفه إلى عدم قبولها- فقد جعله المشرع شرطا للحكم بوقف إجراءات البيع، مما يعني في نفس الوقت عدم اعتباره شرطا لقبولها."},{"kind":"text","text":"الفرع الرابع: أثار رفع الدعوى- الوقف الوجوبي للبيع في أول جلسة"},{"kind":"text","text":"495- لم يشأ المشرع أن يجعل وقف البيع مترتبا بقوة القانون بمجرد رفع دعوى الاستحقاق، إلا أنه رتب نتيجة قريبة من ذلك، وهي وجوب صدور حكم بالوقف في أول جلسة (مادة 1- 302). ولكن يجب أن يكون الحكم بالوقف هنا بناء على طلب المدعي، إذ أن المحكمة- ووفقا لأصول التقاضي- لا يجب أن تحكم بشيء لم يطلبه الخصوم."},{"kind":"text","text":"وبطبيعة الحال أنه إذا لم تتناول دعوى الاستحقاق محل البحث إلا جزءا من العقارات المحجوزة، فلا يقف البيع بالنسبة لباقيها (مادة 1- 303). على أنه يجوز لقاضي التنفيذ أن يأمر -بناء على طلب ذي الشأن- وقف البيع بالنسبة إلى كل العقارات المحجوزة، إذا دعت إلى ذلك أسباب جدية (مادة 2- 303)."},{"kind":"text","text":"الفرع الخامس: آثار استحقاق العقار بعد حكم مرسى المزاد"},{"kind":"text","text":"496- المفروض ألا يحدث هذا الاستحقاق في هذا التوقيت، نظرا لأن البيع موقوف أصلا نتيجة قيام دعوى الاستحقاق، وبالتالي لن يحصل بيع ولن يصدر حكم برسو المزاد، بل وستلغى كل إجراءات التنفيذ إذا استحق رافع الدعوى العقار المحجوز."},{"kind":"text","text":"ومع ذلك ليس مستبعدا أبدا استحقاق العقار بعد حكم مرسى المزاد وذلك في عدة فروض، أهمها أن دعوى استحقاق العقار- والأولى أن تسمى الآن بدعوى ملكية العقار تمييزا لها عن دعوى الاستحقاق المنظمة في المادة 302 - لم ترفع ولم يصدر الحكم فيها إلا بعد حصول البيع وصدور حكم مرسى المزاد."},{"kind":"text","text":"والذي يتضح من المادة 304، أن حكم استحقاق العقار المتأخر هذا سوف يكون مرتبا لذات الآثار التي تترتب عليه في الظروف العادية، أي عند عدم وجود حكم برسو المزاد. فحكم الاستحقاق هنا يجعل بيع العقار بيعا لملك الغير، ومن ثم موقوفا على إجازة المالك. فإذا لم تحدث هذه الإجازة، كان للمحكوم له أن يسترده من المشتري بالمزاد. وعندئذ سيكون للمشتري بالمزاد الرجوع بدعوى شخصية بالثمن وبالتعويضات على الدائن الذي قبض الثمن، أو على المدين الذي انقضى دينه بحصول الدائن على الثمن، ولا يجوز أن تتضمن شروط البيع إعفاء هذا الأخير من رد الثمن."},{"kind":"text","text":"الفرع السادس: الحكم في دعوى استحقاق العقار المحجوز"},{"kind":"text","text":"497- لا يجب أن يغيب عن الذهن أن دعوى استحقاق العقار المحجوز هي دعوى ملكية أساسا، ولذلك فإنه إذا انقضت خصومتها بصدور حكم قضي برفض طلب استحقاق العقار، فإن هذا الحكم ينطوي على حكم آخر ضمني برفض طلب بطلان إجراءات التنفيذ، ومن ثم فلا على الحكم إن لم يعرض لبحث طلب البطلان والرد على أسانيده."},{"kind":"heading","text":"المبحث الرابع: إشكالات التنفيذ (الوقتية)"},{"kind":"text","text":"498- يقصد بإشكالات التنفيذ عموما المنازعات المتعلقة بالتنفيذ، سواء كانت من اختصاص قاضي التنفيذ- وهذا هو الأصل- أو غيره، وسواء كانت من المنازعات الموضوعية أو الوقتية. وقد يقصد بإشكالات التنفيذ معنى ضيقا، بحيث تخرج منه المنازعات الموضوعية وتبقى فقط المنازعات الوقتية على عمومها، أي سواء التي تستهدف وقف التنفيذ مؤقتا أم الاستمرار فيه مؤقتا، وعندئذ تكون العبارة المستعملة هي الإشكال الوقتي. وأخيرا يقصد بإشكالات التنفيذ معنى خاصا ينحي جانبا ليس فقط المنازعات الموضوعية وإنما أيضا الوقتية التي تستهدف الاستمرار في التنفيذ، بحيث يقتصر الأمر على تلك التي تستهدف فقط وقف التنفيذ مؤقتا. هذا المعنى الخاص للإشكال المنطوي على طلب الوقف هو الذي انشغلت به حصريا المادة 239 وما بعدها، رغم عمومية العنوان الذي وردت تحته وهو “إشكالات التنفيذ\"."},{"kind":"text","text":"إجراءات تقديم الإشكال"},{"kind":"heading","text":"499- نحن نتكلم تحديدا عن كيفية تقديم إشكال في التنفيذ بالمعنى الخاص أي طلب وقف التنفيذ المقدم لقاضي التنفيذ."},{"kind":"text","text":"والمستفاد من المادة 239 ومن القواعد العامة أن هذا الإشكال يمكن تقديمه بإحدى طريقتين:"},{"kind":"text","text":"(أ) طلب يقدم إلى القائم بالتنفيذ عند التنفيذ"},{"kind":"text","text":"500- يجيز المشرع تقديم الإشكال من المنفذ ضده إلى القائم بالتنفيذ عند التنفيذ (مادة 1-239). تظهر فائدة هذه الطريقة في سهولتها. إذ يقدم الطلب دون حاجة إلى الانتقال إلى المحكمة أو حتى الدخول إلى موقعها الالكتروني، وإنما إلى القائم بالتنفيذ عند تواجده في موطن المدين للحجز على المنقولات التي لديه مثلا، أو للتنفيذ المباشر. وعلى القائم بالتنفيذ إثبات الطلب في المحضر."},{"kind":"text","text":"تقديم الطلب على هذا النحو يعنى استغناء المشرع بذلك عن الطريقة المعتادة لطلب الحماية القضائية، وهي رفع الدعوى القضائية. فطلب الوقف هنا ليس بصحيفة دعوى، ولا يتوجب إعلانه إلى طالب التنفيذ أو غيره، ولا تتحدد له جلسة يعلن بها الطرفان، ولا تنشأ عنه خصومة. ولذلك فإن ما سيصدر فيه هو قرار، وليس حكما قضائيا، ولا حتى أمرا على عريضة."},{"kind":"text","text":"وإذا كانت عبارة البند (1) من المادة 239 تفيد أن القائم بالتنفيذ سوف يعرض الإشكال على قاضي التنفيذ، ليقرر وقف التنفيذ أو المضي فيه، فإنها تفيد أيضا أنه يجوز للمنفذ ضده أن يعرض هو على قاضي التنفيذ مباشرة ذات الإشكال المقدم منه إلى القائم بالتنفيذ. أي أنه لا مانع من أن يعرض المنفذ ضده إشكاله على القائم بالتنفيذ عند التنفيذ، ثم لا يكتفي بذلك ويعيد عرض ذات الإشكال -بنفسه أو بوكيله- على قاضي التنفيذ، خشية أن يتراخى القائم بالتنفيذ في عرضه عليه."},{"kind":"text","text":"(ب) صحيفة دعوى تودع لدى مكتب إدارة الدعوى بمحكمة التنفيذ"},{"kind":"text","text":"501- الأصل العام أن يكون اللجوء إلى القضاء من خلال الطريق المعتاد، وهو رفع دعوى قضائية إلى المحكمة بناء على طلب المدعي، وذلك بأن يودع صحيفة دعواه -ورقيا أو الكترونيا- لدى مكتب إدارة الدعوى (مادة 1- 44). وتنشأ عنه خصومة بلوازمها. هذا الأصل ينطبق على عموم الدعاوى، موضوعية كانت أم مستعجلة."},{"kind":"text","text":"وبناء عليه، ففي عموم المنازعات الوقتية المطلوب فيها اتخاذ إجراء وقتي يتعلق بالتنفيذ، والمسماة بالإشكال الوقتي في التنفيذ، يكون طريق الدعوى جائزا. ينطبق ذلك بالتأكيد على الإشكال الذي لا يستهدف وقف التنفيذ. مثال ذلك طلب الاستمرار في التنفيذ، والمسمى بالإشكال العكسي."},{"kind":"text","text":"502- ولكن ماذا لو كان المطلوب هو وقف التنفيذ؟ الواقع أنه لا يوجد أبدا ما يمنع من رفع هذا الإشكال إلى قاضي التنفيذ- وهو المختص كأصل عام بالفصل في جميع منازعات التنفيذ بصفة مستعجلة - بالطريق المعتاد لرفع الدعوى."},{"kind":"text","text":"وقد يثور في الذهن تصور مفاده أنه لا يجوز اللجوء إلى هذا الطريق المعتاد، انطلاقا من أن قاعدة ضرورة اتباع الطريق الذي رسمه القانون عند وجود أي مطالبة قضائية. وقد حدد البند (1) من المادة 239 كيفية رفع الإشكال الوقتي الذي يستهدف وقف التنفيذ، وهي أن يتم تقديمه إلى القائم بالتنفيذ كما تبين لنا مما سبق."},{"kind":"text","text":"والحقيقة أنه لا يجب أن يفهم من عبارات البند المشار إليه أن هذه الكيفية هي الطريقة الوحيدة لتقديم الإشكال الوقتي في التنفيذ. فهذا البند يستهدف فقط الإتيان بطريقة خاصة لتقديم الإشكال الوقتي (هي تقديم الإشكال للقائم بالتنفيذ) في فرض محدد (هو عند القيام بالتنفيذ)، ما كان ممكنا اتباعها لولا النص عليها."},{"kind":"text","text":"أما خارج هذا الفرض، فالنص لم يتعرض لكيفية رفع الإشكال. ولذلك فهو لا يحول دون رفع الإشكال الوقتي بالطريق المعتاد، أي بصحيفة دعوى تودع لدى مكتب إدارة الدعوى. وعندئذ تنشأ خصومة، وما يستتبع ذلك من وجوب إعلان صحيفة الإشكال إلى المدعى عليه، وتحديد جلسة، وغير ذلك مما يجري بصدد الدعاوى المستعجلة."},{"kind":"text","text":"آثار تقديم الإشكال الوقتي"},{"kind":"text","text":"503- (أ) الأصل أنه لا يترتب على مجرد تقديم الإشكال الوقتي -أو أي طلب- أي أثر على عملية التنفيذ، وأن هذا الأثر إنما يترتب على القرار القضائي الذي يصدر بعد ذلك. خرج المشرع على هذا الأصل عندما يعرض هذا الإشكال عند التنفيذ، أي على القائم بالتنفيذ. فقد رتب المشرع على تقديمه-مجرد تقديمه – وقف التنفيذ. ويقصد بهذه العبارة تحديدا أنه لا يجوز للقائم بالتنفيذ أن يتم التنفيذ قبل أن يصدر القاضي قراره (مادة 2- 239)."},{"kind":"text","text":"يفهم من ذلك أنه إذا كان التنفيذ مما يجري على مرحلة واحدة، كما لو كان تنفيذا مباشرا، كتسليم عقار أو إخلائه مثلا، فإن معني ألا يتم التنفيذ هنا، أنه يمتنع تماما- وإن كان بصفة مؤقتة- بمجرد تقديم الإشكال."},{"kind":"text","text":"أما إذا كان التنفيذ مما يجري على مراحل، وهو ما ينطبق على التنفيذ بطريق الحجز، فإن تقديم الإشكال للقائم بالتنفيذ يجيز للقائم بالتنفيذ أن يمتنع فورا عن الحجز، ويجيز له أيضا ألا يمتنع ذلك وإنما يقوم بتوقيع الحجز بل وكذلك بالاستمرار فيه – بأن يعين الحارس ويمهد للبيع- على أن يمتنع فقط -ومؤقتا- من الوصول به إلى مرحلته الأخيرة وهي البيع."},{"kind":"text","text":"وإلى أن يصدر قاضي التنفيذ قراره، سوف يظل وقف التنفيذ الذي ترتب بقوة القانون -وبالتحديد السابق- ساريا. فإذا صدر القرار بوقف التنفيذ، ظل الوقف مترتبا. أما إذا صدر القرار بالمضي في التنفيذ، زالت حالة الوقف."},{"kind":"text","text":"504- (ب) إذا قدم الإشكال إلى القائم بالتنفيذ عند التنفيذ أو بالطريق المعتاد، ولكن تبين لقاضي التنفيذ عند عرضه عليه أنه في حقيقة الأمر يعتبر منازعة تنفيذ موضوعية، بالنظر إلى أنه ليس مطلوبا فيه إجراء وقتي هو وقف التنفيذ، وإنما إصدار قرار ينطوي على المساس بأصل الحق في التنفيذ، فعليه عندئذ أن يسبغ على الإشكال المقدم التكييف الصحيح. ولسوف يترتب على ذلك نتيجتان: الأولى أن على قاضي التنفيذ أن يأمر بالمضي في التنفيذ، والثانية أن يصرح لمقدم الإشكال بقيده كإشكال موضوعي بالإجراءات المعتادة لرفع الدعوى (مادة 3-239). ويقصد بهذه العبارة الأخيرة ورغم عدم النص عليها، أن على مقدم الإشكال تحرير صحيفة دعوى يعلنها بعد قيدها إلى المدعى عليه، بحيث تنعقد خصومة قضائية بكل لوازمها. ويجب عل مقدم الإشكال رفع دعواه خلال سبعة أيام عمل من تاريخ التصريح (مادة 3-239)."},{"kind":"text","text":"والأصل أن نفس قاضي التنفيذ الذي قام بالتكييف هو الذي سيكون مختصا بمنازعة التنفيذ الموضوعية."},{"kind":"text","text":"وأيا كانت المحكمة التي ستختص بنظر المنازعة الموضوعية، فإنه يعود إليها هي سلطة القضاء بوقف التنفيذ (مادة 3- 239)."},{"kind":"text","text":"أما إذا كان الاختصاص منعقدا لمحكمة أخرى، فلن يمتنع التكييف. كل ما هنالك أنه يجب توجيه المستشكل إلى رفع دعواه إلى هذه المحكمة."},{"kind":"text","text":"505- (ج) إذا تبين لقاضي التنفيذ أن الإشكال الوقتي يتعلق بدعوى ملكية العقار المحجوز والمرفوعة بالفعل أمام المحكمة المختصة، فإن عليه أن يأمر بوقف التنفيذ. والمفروض أن يستمر الوقف إلا إذا أمرت المحكمة المرفوع أمامها دعوى الملكية هذه بخلاف ذلك (مادة 4-302)."},{"kind":"text","text":"506- (د) إذا عرض إشكال وقتي بطلب وقف التنفيذ، وكان إشكالا تاليا وليس إشكالا أول، فإنه لا يترتب على مجرد تقديمه أي وقف للتنفيذ (مادة 4-239). الحكمة من ذلك، أن القول بغير ذلك يغري المنفذ ضده بأن يرفع الإشكال تلو الإشكال، سواء بنفسه أو بتسخير غيره، فيحول بذلك دون تمام التنفيذ بلا نهاية. هناك فرصة وحيدة إذا لوقف التنفيذ بقوة القانون لمجرد رفع الإشكال هي أن يكون إشكالا أول."},{"kind":"text","text":"على أنه ليس معنى ما سبق أن الإشكال الوقتي اللاحق لا يمكنه أبدا أن يفضي إلى وقف التنفيذ. فالواقع أن البند (5) من المادة 239 ذاتها يسمح لقاضي التنفيذ بأن يأمر بوقف التنفيذ بناء على هذا الإشكال اللاحق."},{"kind":"text","text":"507- (ه) بل إنه حتى الإشكال الأول، لن يوقف التنفيذ بقوة القانون بمجرد رفعه، وذلك إذا كان مرفوعا بعد منازعة تنفيذ موضوعية موقفة للتنفيذ (مادة 239- 4). ففكرة الفرصة الوحيدة للوقف بقوة القانون حاضرة في ذهن المشرع، ولذلك لن يتاح للمنفذ ضده تعطيل التنفيذ بإرادته سوى مرة واحدة، أيا كانت الوسيلة التي استخدمها ورتبت هذا التعطيل."},{"kind":"text","text":"طبيعة القرار الصادر وطريق المراجعة"},{"kind":"text","text":"508- القرار الصادر من قاضي التنفيذ في الإشكال المقدم إلى القائم بالتنفيذ عند التنفيذ، ليس حكما قضائيا لأنه لا يصدر في خصومة. كما أنه ليس أمرا على عريضة - وإن كان قريبا منه- لعدم استعمال النص لعبارات ترجح هذا الوصف. ولكنه يدخل في عداد \"القرارات\"."},{"kind":"text","text":"وتبدو أهمية وصف العمل الذي يصدر عن القضاء، في تحديد كيفية المراجعة القضائية لهذا العمل. وقد أسعفنا المشرع هنا وذكر صراحة خضوع القرار الصادر في الإشكال الوقتي محل البحث للتظلم، وفق البند (1) من المادة (209) (مادة 239 -2)."},{"kind":"text","text":"509- يبقى بعد ذلك، الحكم الصادر في الإشكال الوقتي المقدم بالطريقة الثانية. هذا الحكم هو حكم وقتي أو مستعجل- فالعبارتان مترادفتان- يقبل الطعن بالاستئناف طبقا للقواعد العامة، ويصدر مشمولا بالنفاذ المعجل بقوة القانون (مادة 1-215-أ)."},{"kind":"text","text":"\"وآخر دعواهم أن الحمد لله رب العالمين\""},{"kind":"text","text":"قائمة المراجع"},{"kind":"text","text":"- إجراءات التنفيذ في المواد المدنية والتجارية، دار المطبوعات الجامعية، 2007."},{"kind":"text","text":"- التعليق على نصوص قانون المرافعات، الطبعة الخامسة، منشأة المعارف."},{"kind":"text","text":"- التنفيذ الجبري في المواد المدنية والتجارية دار النهضة العربية، 2005."},{"kind":"text","text":"- عناصر القوة التنفيذية في قانون المرافعات، مطبعة جامعة طنطا، 1998."},{"kind":"text","text":"- طلبات وقف التنفيذ أمام محكمة التنفيذ ومحاكم الطعن في المواد المدنية والتجارية، دار المطبوعات الجامعية، 2003."},{"kind":"text","text":"- مبدأ المواجهة ودوره في التنفيذ الجبري، مجلة الحقوق، العدد الأول، 1998."},{"kind":"text","text":"- الحق في الإخلاء الجبري ونظامه الإجرائي، مجلة الحقوق، العدد الثالث والرابع، 1993."},{"kind":"text","text":"- النظام القانوني لتعدد الحجوز، دار المطبوعات الجامعية، 2000."},{"kind":"text","text":"- الوجيز في قانون الإجراءات المدنية، مطبوعات جامعة الإمارات، 2021."},{"kind":"text","text":"- أصول التنفيذ وفقا لمجموعة المرافعات المدنية والتجارية والتشريعات المرتبطة بها، دار أبو المجد للطباعة، الطبعة الرابعة، 1999."},{"kind":"text","text":"- الأوامر على العرائض وأوامر الأداء، مجلة العلوم القانونية والاقتصادية، يناير 1994، العدد الأول، السنة 36."},{"kind":"text","text":"- آثار إلغاء الأحكام بعد تنفيذها، دار النهضة العربية، بدون تاريخ نشر."},{"kind":"text","text":"- التنفيذ الجبري، دار الجامعة الجديدة، 2016."},{"kind":"text","text":"- الصفة في التنفيذ، دار الجامعة الجديدة، 2000."},{"kind":"text","text":"- التنفيذ الجبري في الإمارات العربية المتحدة، أكاديمية شرطة دبي، 1996."},{"kind":"text","text":"- الإجراءات المدنية للتنفيذ الجبري في قانون المرافعات المصري، دار النهضة العربية، 2000."},{"kind":"text","text":"- التنفيذ المباشر للسندات التنفيذية، دار الجامعة الجديدة، 2001."},{"kind":"text","text":"- أوامر الأداء، الطبعة الثالثة، 1989."},{"kind":"text","text":"- أحكام التنفيذ الجبري وطرقه، منشأة المعارف، الطبعة الثانية، 1971."},{"kind":"text","text":"- التنفيذ المباشر، دار الجامعة الجديدة، 2008."},{"kind":"text","text":"- شرح قانون الإجراءات المدنية الإماراتي، دار الحافظ، 2022."},{"kind":"text","text":"- أصول التنفيذ الجبري، منشورات الحلبي الحقوقية، 2003."},{"kind":"text","text":"- عقبات التنفيذ الجبري، دار المطبوعات الجامعية، 2020."},{"kind":"text","text":"- قواعد تنفيذ الأحكام والمحررات الموثقة في قانون المرافعات الجديد، دار النهضة العربية، 1968."},{"kind":"text","text":"- أصول التنفيذ الجبري وفقا لقانون المرافعات في المواد المدنية والتجارية، بدون ناشر، الطبعة الأولى، 2005."},{"kind":"text","text":"- النظرية العامة للتنفيذ القضائي في قانون المرافعات المدنية والتجارية دار الجامعة الجديدة للنشر، 2017."},{"kind":"text","text":"- حجز ما للعميل لدى البنك، مجلة الحقوق، 2008، العدد الثاني."},{"kind":"text","text":"- التنفيذ الجبري في قانون دولة الإمارات العربية، دراسة مقارنة بالشريعة الإسلامية، مطبوعات جامعة الإمارات العربية المتحدة، 1996."},{"kind":"text","text":"- نظام التنفيذ، دار الفكر العربي، 1968."},{"kind":"text","text":"- أوامر الأداء، مجلة قضايا الحكومة، س2(1908)، العدد الأول."},{"kind":"text","text":"- الوجيز في التنفيذ الجبري في دولة الإمارات العربية المتحدة، إثراء للنشر والتوزيع، الأردن، الطبعة الأولى، 2010."},{"kind":"text","text":"- قواعد وإجراءات التنفيذ الجبري والتحفظ في قانون المرافعات بالمقارنة بأحكام الشريعة الإسلامية، دار الفكر العربي، الطبعة الثانية، 1980."},{"kind":"text","text":"- النظام المستحدث لقاضي تنفيذ الأحوال الشخصية في محاكم دولة الإمارات العربية المتحدة، مجلة الحقوق، جامعة الكويت، تحت النشر."},{"kind":"text","text":"- قواعد التنفيذ الجبري في قانون المرافعات، دار النهضة العربية، 2001."},{"kind":"text","text":"- نظام قاضي التنفيذ في القانون المصري والمقارن، دار النهضة العربية، 1978."},{"kind":"text","text":"- قواعد التنفيذ الجبري في قانون المرافعات، دار النهضة العربية، 2001."},{"kind":"text","text":"- مستحدثات قانون التنفيذ الجبري الفرنسي الجديد، مجلة الحقوق الكويتية، العدد الأول، السنة الأربعين، مارس 2016."},{"kind":"text","text":"- أصول التنفيذ الجبري في قانون الإجراءات المدنية والتجارية، دار الجامعة الجديدة للنشر، 2012."},{"kind":"text","text":"- التنفيذ الجبري في دولة الإمارات العربية المتحدة، طبعة أكاديمية شرطة دبي، الطبعة الثانية، 2002."},{"kind":"text","text":"- شرح إجراءات التنفيذ الجبري وفقا لقانون الإجراءات المدنية الاتحادي، دار النهضة العربية (مصر)، الطبعة الأولى، 2009."},{"kind":"text","text":"- أصول التنفيذ الجبري وفقا لمجموعة المرافعات المدنية والتجارية والتشريعات المكملة لها، دار النهضة العربية، 1995."},{"kind":"text","text":"- التنفيذ الجبري في المواد المدنية والتجارية، دار النهضة العربية، 1995."},{"kind":"text","text":"- مبادئ التنفيذ، دار النهضة العربية، الطبعة الرابعة، 1978."},{"kind":"text","text":"- أصول التنفيذ الجبري، دار الفكر العربي، 1983."},{"kind":"text","text":"- التنفيذ الجبري في دولة الإمارات العربية المتحدة، أكاديمية شرطة دبي، الطبعة الثانية."},{"kind":"text","text":"- قواعد التنفيذ الجبري وإجراءاته في قانون المرافعات، دار أبو المجد للطباعة، الطبعة الثانية، 1991."},{"kind":"text","text":"- المقومات الموضوعية والشكلية للسند التنفيذي، دار الفكر العربي، الطبعة الأولى، 2008."},{"kind":"text","text":"- الوجيز في التنفيذ الجبري وفقا للائحة التنظيمية لقانون الإجراءات المدنية لدولة الإمارات العربية المتحدة، دار الآفاق العلمية للنشر والتوزيع، الطبعة الخامسة،2020."},{"kind":"text","text":"- النظام القانوني للإشراف والرقابة على إجراءات التنفيذ الجبري، دار الجامعة الجديدة للنشر، الطبعة الثانية، 2009."},{"kind":"text","text":"- الاختصاص النوعي بالفصل في منازعات التنفيذ الجبري، مجلة الأمن والقانون (تصدرها أكاديمية شرطة دبي)، السنة 24، العدد 1، يناير 2016."},{"kind":"text","text":"- الوسيط في التنفيذ الجبري للأحكام وغيرها من السندات التنفيذية، دار الجامعة الجديدة للنشر، 2000."},{"kind":"text","text":"- إشكالات التنفيذ الجبري الوقتية والموضوعية، دار الجامعة الجديدة، 2011."},{"kind":"text","text":"- دعوى استرداد المنقولات المحجوزة، دار الجامعة الجديدة، بدون سنة نشر."},{"kind":"text","text":"- الشروط الخاصة للتنفيذ ضد الكفيل، مجلة روح القوانين، يناير 2005، العدد 34، الجزء الثاني."},{"kind":"text","text":"- مذكرات في التنفيذ الجبري، بدون ناشر، 1986."},{"kind":"text","text":"- حول جواز الطعن المباشر في الأحكام الصادرة في طلبات وقف النفاذ المعجل، مجلة العلوم القانونية والاقتصادية، السنة 18 العدد الأول يناير 1976."},{"kind":"text","text":"- Voies d’exécution, 11e éd., Sirey, 2013."},{"kind":"text","text":"- Réforme des procédures civiles d’exécution. Jur.Cl. Pr.Civ., 1994, Fasc. 2."},{"kind":"text","text":"- Voies d’exécution et procédure de distribution, 18e éd., 1995."},{"kind":"text","text":"الفهرس"},{"kind":"heading","text":"مقدمة 2"},{"kind":"heading","text":"الباب الأول: أركان التنفيذ 5"},{"kind":"heading","text":"الفصل الأول: السند التنفيذي 5"},{"kind":"heading","text":"المبحث الأول: الحكم القضائي 6"},{"kind":"heading","text":"المطلب الأول: الشروط الواجب توافرها في الحكم القضائي كسند تنفيذي 6"},{"kind":"text","text":"الفرع الأول: الشرط الأول - أن يكون الحكم صادرا في الموضوع 7"},{"kind":"text","text":"الفرع الثاني: الشرط الثاني- أن يكون الحكم صادرا بإلزام 8"}]);
